export default {id:"curse_of_strahd",title:"史特拉德的詛咒",titleEn:"Curse of Strahd",levels:"3-9",startLevel:3,deep:!0,synopsis:"被迷霧困在巴洛維亞，冒險者必須找回三件聖物、找到命定的盟友，才有機會對抗不死的領主史特拉德·馮·扎羅維奇。先去哪裡、幫誰、放棄誰，都由隊伍決定，而每個決定都會回來找他們。",setting:"哥德恐怖",flags:{house_appeased:"在死亡之屋向祭壇獻上了生命，這件事跟著他們",house_defied:"拒絕了死亡之屋的獻祭，殺出了一條路",children_rest:"讓羅斯與索恩的遺骨入土，兩個孩子安息了",children_follow:"沒有安葬孩子，他們的幽靈仍跟在某個人身上",ireena_with_party:"伊蕾娜與隊伍同行",ireena_left_behind:"伊蕾娜留在巴洛維亞村，史特拉德下一次來訪時沒有人擋在門口",ismark_ally:"伊斯馬克把隊伍當成戰友",burgomaster_buried:"老村長在教堂墓地安葬了",doru_freed:"多魯得到了解脫，東納維奇神父恢復了神智",doru_loose:"多魯逃出了教堂地窖，在村裡獵食",reading_done:"瑪丹伊娃為隊伍占卜過了",hags_slain:"老骨磨坊的鬼婆被消滅，夢糕不再流出",hags_bargain:"與老骨磨坊的鬼婆做了交易",children_saved_mill:"救出了磨坊裡的孩子",strahd_met_road:"史特拉德在路上親自打量過隊伍",bones_returned:"聖安卓的遺骨回到了教堂",church_fell:"聖安卓教堂在吸血鬼衍體的襲擊中失守",baron_ally:"瓦爾加斯男爵把隊伍當成自己人",baron_enemy:"瓦爾加斯男爵下令通緝隊伍",baron_deposed:"瓦爾加斯男爵倒台",wachter_rules:"菲歐娜·華特掌握了瓦拉基",wachter_exposed:"華特夫人的邪教被揭發",izek_knows_ireena:"伊澤克認出伊蕾娜就是他失散的妹妹",rictavio_trusts:"里克塔維奧（范李希頓）信任隊伍",arabelle_saved:"從贊湖救回了阿拉貝兒，維斯塔尼營地欠隊伍一份情",arabelle_lost:"阿拉貝兒沉入了贊湖",keepers_friend:"羽翼守護者（馬提科夫家）視隊伍為朋友",winery_saved:"魔法師之酒莊奪回來了",gem_recovered:"昨日山丘的寶石回到了酒莊",wintersplinter_fell:"巨木枯萎怪在昨日山丘被阻止",winery_burned:"酒莊被毀，巴洛維亞的酒斷了",ezmerelda_ally:"艾茲梅瑞妲與隊伍合作",tower_destroyed:"范李希頓的塔被炸毀",werewolves_emil:"狼人群由埃米爾帶領，不再擄走孩子",werewolves_hostile:"狼人群視隊伍為獵物",krezk_trusts:"克雷茲克的村民信任隊伍",abbot_exposed:"隊伍看穿了修道院長的瘋狂",abbot_bride:"修道院長把瓦希爾卡當成新娘送往鴉閣城堡",ilya_raised:"村長的兒子伊利亞被修道院長復活",pool_blessing:"伊蕾娜在聖池邊想起了自己是誰",ireena_taken:"伊蕾娜落入了史特拉德手中",skull_returned:"銀龍的頭骨回到了宅邸，燈塔再度亮起",vladimir_released:"弗拉迪米爾放下了仇恨",vladimir_enemy:"銀龍騎士團的亡魂與隊伍為敵",baba_slain:"芭芭·莉薩迦死了",dark_gift_taken:"有人在琥珀神殿接受了黑暗力量的饋贈",exethanter_restored:"神殿的巫妖想起了自己的名字",strahd_secret_known:"隊伍知道了史特拉德與黑暗力量立約的真相",kasimir_patrina:"卡西米爾復活了妹妹帕翠娜",dinner_accepted:"隊伍接受了史特拉德的晚宴邀請",heart_destroyed:"悲傷之心被摧毀，城堡不再替史特拉德承受傷害",brides_dealt:"城堡裡的新娘不再是威脅",rahadin_slain:"總管拉哈丁死了"},fortune:{reader:"瑪丹伊娃",revealAt:"2-C1",draws:[{key:"tome",name:"史特拉德之書",options:[{site:"vallaki_church",where:"藏在教堂地板下、原本放聖骨的暗格更深處",hint:"找一處失去了守護的聖所；它在空了的地方底下。"},{site:"winery",where:"夾在酒窖最老一排酒桶後的帳冊裡",hint:"到釀出這片土地最後一點歡樂的地方去；它在最老的木頭後面。"},{site:"argynvostholt",where:"在二樓禮拜堂，一名亡魂騎士跪著守著它",hint:"找一位死去的龍；向跪著的人問它。"},{site:"berez",where:"埋在瑪琳娜紀念碑的基石下",hint:"在被洪水吞掉的村子裡，有一塊為愛而立的石頭。"}]},{key:"symbol",name:"渡鴉聖徽",options:[{site:"krezk",where:"在修道院長的房間，掛在一尊未完成的雕像頸上",hint:"找那位不是人的治療者；他把它給了他的作品。"},{site:"vallaki_inn",where:"藏在藍水旅店閣樓的渡鴉巢裡，由馬提科夫家看管",hint:"藍色的水，黑色的羽毛；主人只把它交給朋友。"},{site:"yester_hill",where:"埋在石圈中央，被樹根纏著",hint:"在祖先的山丘上，樹根握著它。"},{site:"mill",where:"在磨坊頂層，鬼婆把它當成戰利品鎖在箱子裡",hint:"甜食的來處；三個女人把它鎖起來。"}]},{key:"sword",name:"太陽劍",options:[{site:"amber_temple",where:"在神殿深處的寶庫，劍柄躺在琥珀石棺之間",hint:"到山裡被遺忘的知識那裡去；光在琥珀之間睡著。"},{site:"argynvostholt",where:"在銀龍的墓室裡，和龍的遺骨葬在一起",hint:"龍的安息處；光與骨頭躺在一起。"},{site:"werewolf_den",where:"在狼人巢穴最深處的祭壇上，被當成供品",hint:"狼向牠們的母親獻上了一道光。"},{site:"tower",where:"在范李希頓的塔頂，鎖在他的箱子裡",hint:"湖上的塔；獵人把它和他的秘密鎖在一起。"}]},{key:"ally",name:"命定的盟友",kind:"ally",options:[{site:"vallaki_inn",who:"里克塔維奧（魯道夫·范李希頓）",where:"他以馬戲團團長的身分住在藍水旅店",hint:"找一個戴著面具過日子的獵人；他和一頭怪物一起旅行。"},{site:"tower",who:"艾茲梅瑞妲·達瓦尼爾",where:"她躲在老師的塔附近，隨時可能現身",hint:"找一個失去了一條腿卻沒有失去膽子的女人。"},{site:"argynvostholt",who:"高弗瑞·格威林爵士",where:"他是宅邸裡還記得誓言的亡魂騎士",hint:"一個死了還守著誓言的騎士；他在龍的家裡。"},{site:"werewolf_den",who:"祖萊卡·托倫斯卡",where:"她在狼人巢穴裡等丈夫埃米爾回來",hint:"一個有狼的心的女人；她只想要丈夫回家。"},{site:"krezk",who:"瓦希爾卡",where:"修道院長用屍塊縫成的少女，還不知道自己是什麼",hint:"一個被做出來的女孩；她比做她的人更有人性。"}]},{key:"enemy",name:"最後的對決",kind:"place",options:[{where:"城堡禮拜堂，史特拉德坐在第一排長椅上等著",hint:"他在自己曾經跪過的地方。"},{where:"北塔頂的悲傷之心旁",hint:"他在城堡的心跳旁邊。"},{where:"地下墓穴，他自己的棺槨前",hint:"他在自己的墳前。"},{where:"大宴會廳的管風琴前",hint:"他在音樂響起的地方。"},{where:"瑟蓋的墓前",hint:"他在他弟弟長眠的地方。"}]}]},sanity_mechanics:{system:"恐懼與絕望",description:"在巴洛維亞，恐懼是史特拉德的武器。他不急著殺人，他要的是看人慢慢放棄。",triggers:["目睹極度恐怖的場面","被史特拉德當面玩弄","同伴倒下","在琥珀神殿與黑暗力量接觸"],effects:["恐懼：不敢靠近恐懼的來源","短暫的失常：幻覺、僵住、不受控制的舉動","長期的改變：多疑、貪婪、冷漠","向黑暗求助：為了力量付出不該付的代價"],recovery:"在祝聖過的地方好好休息、被同伴拉回來、或做了一件真正英勇的事。"},truth:{cause:"史特拉德為了長生與奪回弟弟的未婚妻塔蒂亞娜，與黑暗力量立約，在弟弟的婚禮上殺了他；塔蒂亞娜跳下城牆。",motive:"塔蒂亞娜的靈魂一再轉世，這一世是伊蕾娜。史特拉德要她，每一次都失去她。",threat:"巴洛維亞是他的牢籠也是他的領地。他把外來者當成解悶的玩物，也在其中尋找繼承人或對手。",turn:"他不會被永遠殺死，除非詛咒本身被打破；但他可以被擊敗，迷霧會暫時散去。",endings:["擊敗史特拉德，迷霧散去，隊伍離開","隊伍敗亡或臣服","有人接受黑暗力量，成為下一個他"],people:["伊蕾娜是塔蒂亞娜的轉世","里克塔維奧就是范李希頓","藍水旅店的馬提科夫家是渡鴉化身人","修道院長是墮落的天界生物"]},acts:[{act:1,title:"死亡之屋",titleEn:"Death House",levelRange:"3",objective:"活著離開那棟不放人走的宅子",keyEvents:["兩個孩子在霧中求救","宅子裡沒有活人，卻處處有人住過的痕跡","地下室傳來吟唱"],opening_text:"霧是忽然起的。等你們發現路不見了，身後的樹林也不見了。前方只有一條泥路、一座死氣沉沉的村子，和路邊一棟四層樓的老宅。兩個孩子站在宅門前，渾身濕透。",sites:[{id:"death_house",name:"杜斯特宅邸",map:"haunted_manor",blurb:"一棟體面得過了頭的磚造老宅，門開著，裡面的燈亮著，餐桌上的菜還是熱的。",secret:"杜斯特夫婦生前主持一個崇拜史特拉德的邪教，在地下室拿過路人獻祭。兩個孩子被關在閣樓餓死，如今成了誘餌。宅子本身有意志，要的是再一次獻祭。"}],npcs:[{site:"death_house",name:"羅斯",role:"引路的孩子",description:"十歲的男孩，護著妹妹，說地下室有怪物。他不知道自己已經死了。",secrets:"他和妹妹是幽靈的幻象，真正的遺骨在閣樓。",voice:"帶著哭腔與寒意的稚嫩小女孩顫音，赤足站在濃霧中瑟瑟發抖，小手死死攥著弟弟。",flaw:"早已在死亡之屋的閣樓中餓死，身為幻影幽魂，極度懼怕回憶起地下室父母的邪教血祭真相。",tactics:"毫無戰鬥力，只能以悲泣哭聲擾亂敵人心神，在迷霧中為隊伍指引安全石階。",deal:"承諾為她和弟弟找回遺骸並予以體面安葬，她會指出閣樓暗門與通往地窖的安全通風道。"},{site:"death_house",name:"索恩",role:"引路的孩子",description:"七歲的女孩，抱著一個布娃娃，不肯進屋。",voice:"緊抱破舊玩具熊、抽泣著不敢抬頭的幼童嗓音，說話時總躲在姐姐身後。",flaw:"靈魂極度脆弱，一聽到地下室傳來的怪獸低吼便會陷入尖叫癱瘓。",tactics:"毫無戰鬥力，遇到危險會蜷縮在牆角，其純潔的靈魂微光能短暫驅散低階幽魂的敵意。",deal:"將其遺骨放入小棺材中安息，能獲得其純潔靈魂的庇護，全隊在死亡之屋內獲得一次意志豁免優勢。"},{site:"death_house",name:"伊莉莎白·杜斯特",role:"女主人的亡魂",description:"畫像裡高傲的女人。她恨丈夫的私生子，也恨打擾她的人。",secrets:"她的信藏在書房暗格，寫明了邪教與史特拉德的冷淡回信。",voice:"尖銳瘋癲、伴隨食屍鬼般咀嚼聲的怨毒女高音，長袍下露出枯槁的腐爛爪刃。",flaw:"生前狂熱崇拜黑暗邪神而活埋親生子女，對「孩子」與「母親」字眼懷有極端的精神狂躁。",tactics:"隱匿於祭壇陰影發動尖嘯偷襲，召喚四隻地窖食屍鬼合圍，自身以枯萎之爪撕裂獵物喉嚨。",deal:"狂熱的邪教女主人無法溝通；唯有當面揭露其邪教儀式實為一場騙局，其精神防禦會崩潰一輪。"}],encounters:["活化鎧甲","幽影","食屍鬼","屍妖"],treasures:["杜斯特家的地契","邪教的銀匕首","寫給史特拉德的信"],endCondition:"隊伍離開了宅子，站在巴洛維亞村的泥路上",strategic_nodes:[{id:"1-A",site:"death_house",map:"haunted_manor",title:"太乾淨的房子",situation:"孩子們說怪物在地下室，卻不肯跟進來。屋裡一塵不染，壁爐燒著，沒有任何人。每一幅畫像都像在看著訪客。",approaches:[{type:"搜查",check:"調查 DC 12",outcome:"在書房找到暗格、信件與通往閣樓的暗梯線索"},{type:"安撫孩子",check:"說服 DC 12",outcome:"羅斯說出爸媽把他們鎖在房間裡，還有「另一個寶寶」"},{type:"直接上樓",check:"察覺 DC 13",outcome:"注意到走廊的盔甲位置變過"}],fail_forward:"盔甲在背後動了起來，隊伍被逼著往樓上退，門在身後一扇一扇關上。",foes:[["animated_armor",1]]},{id:"1-B",site:"death_house",map:"haunted_manor",title:"閣樓的小房間",situation:"閣樓有一扇從外面上鎖的門。裡面是兩張小床，兩具抱在一起的小小骸骨，和一座精確複製整棟宅子的玩具屋，連暗門都做了出來。",approaches:[{type:"答應安葬",check:"說服 DC 10",outcome:"孩子們的幽靈平靜下來，指出玩具屋裡通往地下的暗門"},{type:"研究玩具屋",check:"調查 DC 12",outcome:"找到地下室入口與祭壇的位置"},{type:"強行帶走遺骨",check:"無",outcome:"幽靈驚慌，試圖附在某個人身上"}],fail_forward:"孩子們哭喊著不要被留下，其中一個鑽進了某位隊員身體裡，帶著他的害怕一起走。",calm:!0,sets:{success:["children_rest"],setback:["children_follow"]}},{id:"1-C",site:"death_house",map:"crypt_hall",title:"地下的家族墓穴",situation:"暗梯通往比房子大得多的地下。杜斯特家的墓室一間一間排開，其中兩間是空的，名牌寫著羅斯與索恩。遠處有很多人在齊聲吟唱。",approaches:[{type:"安葬遺骨",check:"宗教 DC 11",outcome:"把孩子放進他們的墓室；吟唱聲停了一拍"},{type:"循聲潛行",check:"隱匿 DC 13",outcome:"避開遊蕩的東西，看見祭壇室的全貌"},{type:"正面清出一條路",check:"開戰",outcome:"食屍鬼從壁龕裡爬出來"}],fail_forward:"墓穴裡的東西醒了一大半，隊伍一路被追到祭壇室，沒有退路。",foes:[["ghoul",2]],ifs:[["children_rest","孩子們已經答應會安息，把遺骨放進墓室時不需要檢定"],["children_follow","被附身的隊員在這裡不由自主地走向空的墓室"]]},{id:"1-D",site:"death_house",map:"infernal_temple",title:"他也必須死",situation:"積水的祭壇室。看不見的信眾在四周吟唱，聲音要求一次獻祭。祭壇上的鎖鏈是空的。水裡有東西在等。",approaches:[{type:"獻上生命",check:"無",outcome:"宅子滿足了，放隊伍離開；動手的人永遠記得這一刻"},{type:"拒絕",check:"開戰",outcome:"吟唱變成怒吼，水裡的東西站了起來"},{type:"揭穿它",check:"宗教 DC 15",outcome:"指出史特拉德從未回應過這些信徒；吟唱動搖，怪物變弱"}],fail_forward:"隊伍被打倒，卻沒有死。醒來時躺在宅子外的泥地上，每個人的行囊裡多了一封字跡優雅的歡迎信。",foes:[["wight",1],["shadow",2]],sets:{success:["house_defied"],setback:["house_appeased"]}},{id:"1-E",site:"death_house",map:"haunted_manor",title:"房子不放人",situation:"往上的路全變了。門框裡是旋轉的刀刃，牆裡擠滿老鼠，煙從每一道縫湧出來。宅子在用盡一切把人留下。",approaches:[{type:"衝過刀門",check:"特技 DC 14",outcome:"帶著幾道口子衝了出去"},{type:"破牆",check:"運動 DC 14",outcome:"在老鼠湧出來之前撞開一條路"},{type:"找玩具屋裡的暗道",check:"調查 DC 13",outcome:"從僕人通道繞出去，幾乎毫髮無傷"}],fail_forward:"每個人都帶著傷和滿肺的煙倒在門外。宅子在背後安靜下來，燈還亮著。",foes:[],ifs:[["house_appeased","宅子已經得到獻祭，這一段沒有刀門與濃煙，只有長得不合理的走廊與背後的注視"],["children_rest","孩子們的聲音替隊伍指出哪一扇門是真的"]]}]},{act:2,title:"巴洛維亞村",titleEn:"Village of Barovia",levelRange:"4",objective:"弄清楚這片土地的規矩，聽一次占卜，決定要不要帶走村長的女兒",keyEvents:["村長死了三天還沒下葬","史特拉德夜夜來訪","塔瑟湖邊的維斯塔尼人在等客人"],opening_text:"村子很安靜，不是睡著了的那種安靜。窗後有人，卻沒有人開門。唯一的聲音是某棟屋子裡一個女人的哭聲，和酒館招牌在風裡的吱呀聲。",sites:[{id:"village",name:"巴洛維亞村",map:"village_square",blurb:"泥濘的街道、釘死的窗戶、一間還開著的酒館，和山丘上的村長宅。",secret:"史特拉德已經咬過伊蕾娜兩次。村民怕的不只是他，也怕她把他引來。",ifSkipped:{flag:"ireena_left_behind",text:"沒有人帶走伊蕾娜。"}},{id:"tser_pool",name:"塔瑟湖營地",map:"river_camp",blurb:"河邊的幾輛篷車和一頂大帳篷。維斯塔尼人圍著營火喝酒，像是早就知道有人要來。",rumour:"酒館裡的人說，那裡有個老婦人什麼都看得見。",secret:"瑪丹伊娃是史特拉德同父異母的妹妹，她不會說。她真心想要他被擊敗。"},{id:"mill",name:"老骨磨坊",map:"woodland_cottage",optional:!0,blurb:"山坡上一座歪斜的風車磨坊，烏鴉停滿了屋頂，卻不肯靠近門口。",rumour:"村裡的夢糕是從那裡來的。吃了的人不再難過，也不再醒著。",secret:"三個鬼婆用孩子的骨頭磨粉做糕。村民拿孩子換糕。",ifSkipped:{text:"夢糕繼續流進村子。"}},{id:"svalich_road",name:"斯瓦利奇老路",map:"grassy_crossroads",blurb:"穿過森林往西的唯一一條路。路口有一座絞刑架，和通往鴉閣城堡的岔路。",secret:"史特拉德會在這條路上第一次親自看看來客。"}],npcs:[{site:"village",name:"伊斯馬克·科里亞諾維奇",role:"村長之子",description:"村民叫他「小伊斯馬克」，笑他不如父親。他只想讓妹妹活下去。",interaction:"只要有人肯護送伊蕾娜去瓦拉基，他什麼都願意給。",voice:"堅毅沉重但透著深深無力感的年輕貴族男子嗓音，握劍的指節泛白。",flaw:"深愛妹妹伊蕾娜，在妹妹受到威脅時極易感情用事失去冷靜。",tactics:"熟練運用重劍防禦陣型，以身作盾為伊蕾娜阻擋致命撲咬，具備合格的近戰護衛能力。",deal:"只要小隊答應護送伊蕾娜前往聖安德烈教堂避難，他願奉上家族全部家當並誓死隨隊作戰。"},{site:"village",name:"伊蕾娜·科里亞納",role:"村長養女",description:"紅髮，頸上有兩道咬痕，比哥哥更冷靜。她不想逃，但更不想害死別人。",secrets:"她是塔蒂亞娜的轉世，自己不知道，只是常夢見一個她不認識的年輕人。",voice:"清澈堅定、帶著貴族少女的高貴與不屈決心的嗓音，頸部帶著兩道淡淡的獠牙咬痕。",flaw:"作為塔蒂亞娜的轉世，其靈魂散發的宿命氣息會本能引來史特拉德的瘋狂追逐。",tactics:"不甘為柔弱人質，精通隨身細劍刺殺與自衛搏擊，在絕境中寧願玉碎也絕不向吸血鬼屈服。",deal:"只要小隊展現出對抗伯爵的堅定意志，她會成為全隊最勇敢的戰友，並在關鍵時刻激發宿命抗力。"},{site:"village",name:"東納維奇神父",role:"教堂神父",description:"一年沒睡好的人。整夜祈禱，聲音已經啞了。",secrets:"他的兒子多魯跟著一位法師去攻打城堡，回來時成了吸血鬼衍體，被他鎖在地窖。",voice:"精神瀕臨崩潰、胡言亂語的衰老神父嗓音，手中破舊聖徽在燭光下顫抖。",flaw:"將被轉化為吸血鬼衍體的兒子多魯鎖在地下室，陷入信仰崩塌與父愛撕扯的無盡折磨。",tactics:"喪失戰鬥意志，僅能引導微弱的晨曦之神祝福，遇到衝突只會跪地痛哭祈禱。",deal:"答應為其子多魯尋求靈魂解脫並為其守密，他會獻出教堂密藏的聖水與晨曦之光祝福符文。"},{site:"village",name:"瑪麗",role:"失去女兒的母親",description:"日夜哭泣。她的女兒葛楚妲一週前不見了。",secrets:"葛楚妲被史特拉德帶進了城堡。",voice:"淒厲絕望、抱著無頭破洋娃娃日夜痛哭的瘋癲母親嗓音，哭聲迴盪在空蕩的小屋內。",flaw:"女兒葛楚妲失蹤讓她神智全失，對任何敲門聲都神經質地尖叫或撲咬。",tactics:"毫無戰鬥力，遇險會揮舞生鏽剪刀狂亂揮刺。",deal:"承諾前往鴉閣堡探尋其女兒下落，她會將壓箱底的祖傳純銀小刀與破舊家譜相贈。"},{site:"tser_pool",name:"瑪丹伊娃",role:"維斯塔尼占卜師",description:"很老很老的女人，說話時像是在唸一封早就寫好的信。",voice:"蒼老神祕、彷彿洞悉多元宇宙宿命起落的吉普賽老巫婆腔調，洗牌動作優雅從容。",flaw:"恪守命運塔羅卡牌的古老中立誓言，即便預見毀滅也絕不直接干涉凡人因果。",tactics:"身為高階維斯塔尼占卜宗師，周身環繞命運防護力場，能以心靈凝視瞬間驅散敵意。",deal:"只要小隊恭敬呈上塔羅占卜之禮，她會翻開宿命卡牌，精準揭示三件聖物、盟友與決戰之地。"},{site:"tser_pool",name:"史坦尼米爾",role:"營地的說書人",description:"愛喝酒也愛講古，會說一個王子救了維斯塔尼人的故事。",voice:"豪邁溫暖、圍著篝火彈奏魯特琴的維斯塔尼老說書人腔調，故事娓娓道來引人入勝。",flaw:"骨子裡對史特拉德伯爵懷有古代血盟敬畏，在涉及城堡核心機密時會巧妙避重就輕。",tactics:"撥動琴弦施展吟遊惑控與催眠法術，擅長在醉酒與歡歌中掩護族人後撤。",deal:"只要陪其痛飲上等葡萄酒並傾聽古老傳說，他會贈予小隊不受濃霧迷失的通行護符。"},{site:"mill",name:"莫嘉莎",role:"賣糕的老婦",description:"親切得令人不舒服的老太太，推著小車賣糕。",secrets:"鬼婆之首。兩個「女兒」在樓上。",voice:"假裝慈祥和藹、拉長聲調叫賣「夢境糕點」的駝背老婦，眼底閃爍著惡毒的綠芒。",flaw:"實為夜鬼婆首領，以孩童骨粉製作致幻糕點，極度貪婪且畏懼晨曦神聖之火。",tactics:"隱入以太位面穿梭突襲，施展睡眠術、夢魘侵蝕與衰竭射線，指甲淬有劇毒。",deal:"只要小隊假裝對其血腥買賣視而不見，她會出售能短暫提供超自然幻夢力量的秘制糕點。"},{site:"svalich_road",name:"史特拉德·馮·扎羅維奇",role:"巴洛維亞的領主",description:"彬彬有禮，像主人在打量遠道而來的客人。",tactics:"召喚狼群與蝙蝠狂潮，化霧瞬移，輕抬手指便能施展魅惑人類與高階護盾偏折攻擊。",voice:"優雅高貴、極具統治者威嚴與殘酷玩味的領主男中音，每一字都帶著絕對的主宰力量。",flaw:"極度自負傲慢，將闖入者視為供其消遣的老鼠，在初遇時不屑於直接碾殺獵物。",deal:"以最高規格的貴族禮節向小隊發出鴉閣堡晚宴邀請函，嘲弄小隊的掙扎並享受貓捉老鼠的樂趣。"}],encounters:["殭屍","野狼","恐狼","吸血鬼衍體","報喪女妖"],treasures:["伊斯馬克的家傳佩劍","教堂的聖水","維斯塔尼人的護身符"],endCondition:"隊伍離開了巴洛維亞村一帶，往西走",strategic_nodes:[{id:"2-A1",site:"village",map:"small_inn",title:"血藤酒館",situation:"酒館裡只有三個維斯塔尼女人、一個擦杯子的老闆，和角落裡獨自喝酒的年輕人。他看見外地人，站了起來。",approaches:[{type:"聽他說",check:"說服 DC 10",outcome:"伊斯馬克請隊伍護送妹妹去瓦拉基，並說出村裡的情形"},{type:"向維斯塔尼人打聽",check:"洞悉 DC 13",outcome:"她們提到塔瑟湖的瑪丹伊娃在等「霧帶來的人」"},{type:"問老闆",check:"調查 DC 12",outcome:"聽說了夢糕、哭泣的瑪麗和三天沒下葬的村長"}],fail_forward:"話不投機。伊斯馬克失望地離開，隊伍得自己摸清這個村子，而且慢了一步。",calm:!0,sets:{success:["ismark_ally"]}},{id:"2-A2",site:"village",map:"woodland_cottage",title:"村長的宅子",situation:"宅子的牆上全是爪痕，窗戶釘著木板。伊蕾娜隔著門問來者是誰。大廳裡，她的父親躺在一口粗糙的棺材中，已經三天了。",approaches:[{type:"取得她的信任",check:"說服 DC 12",outcome:"伊蕾娜開門，談起夜裡來訪的「他」，並願意考慮離開"},{type:"檢查宅子",check:"調查 DC 12",outcome:"從爪痕和咬痕判斷來的不只是狼"},{type:"直說來意",check:"洞悉 DC 11",outcome:"看出她其實在保護哥哥，不是被保護的那個"}],fail_forward:"入夜時，狼群又圍住了宅子。隊伍守了一夜，早上所有人都更累，也更清楚留下來不是辦法。",foes:[["wolf",4],["dire_wolf",1]],ifs:[["ismark_ally","伊斯馬克先替隊伍敲了門，伊蕾娜一開始就願意談"]]},{id:"2-A3",site:"village",map:"burial_chambers",title:"埋葬父親",situation:"沒有人敢幫忙抬棺。教堂的屋頂塌了一半，神父還在裡面祈禱，地板下傳來一個年輕人的聲音，說他好餓。",approaches:[{type:"請神父主持葬禮",check:"說服 DC 12",outcome:"東納維奇為老村長安葬，並求隊伍別管地窖"},{type:"下地窖",check:"開戰",outcome:"多魯撲了上來；他還認得父親"},{type:"讓父子說話",check:"洞悉 DC 14",outcome:"多魯清醒了片刻，求人結束這一切"}],fail_forward:"多魯撞開了地窖門逃進夜裡。神父跪在原地，葬禮草草結束。",foes:[["vampire_spawn",1]],sets:{success:["burgomaster_buried","doru_freed"],setback:["burgomaster_buried","doru_loose"]}},{id:"2-A4",site:"village",map:"village_square",title:"走，還是留",situation:"葬禮之後，伊蕾娜得做決定。伊斯馬克要她走。村民希望她走。她看著隊伍，想知道這些外地人值不值得她賭。",approaches:[{type:"承諾護送她",check:"說服 DC 12",outcome:"伊蕾娜與伊斯馬克同行，往瓦拉基去"},{type:"讓她自己決定",check:"洞悉 DC 12",outcome:"她選擇同行，而且因為被當成一個人而不是包袱，更信任隊伍"},{type:"勸她留下",check:"無",outcome:"她留在村裡，伊斯馬克留下來陪她"}],fail_forward:"爭執沒有結論。當晚史特拉德又來了，隔天早上伊蕾娜的臉色比紙還白，還是留在了村裡。",calm:!0,sets:{success:["ireena_with_party"],setback:["ireena_left_behind"]},ifs:[["doru_loose","村民把多魯逃走的事怪在隊伍頭上，有人朝他們丟石頭"],["!burgomaster_buried","父親還沒下葬，伊蕾娜不肯離開"]]},{id:"2-C1",site:"tser_pool",map:"river_camp",title:"瑪丹伊娃的帳篷",situation:"帳篷裡很暗，一張矮桌，一副舊得發亮的牌。老婦人沒有抬頭就叫出了隊伍裡某個人的名字。",approaches:[{type:"請她占卜",check:"無",outcome:"她翻開五張牌：三件聖物、一位盟友、一個地點"},{type:"追問她是誰",check:"洞悉 DC 16",outcome:"她笑了，只說她也有一個不成材的哥哥"},{type:"問史特拉德的事",check:"歷史 DC 13",outcome:"她說了一個王子、一個弟弟和一場婚禮的故事"}],fail_forward:"牌還是翻了。只是老婦人說得更含糊，像是不確定這些人聽得懂。",calm:!0,sets:{success:["reading_done"],setback:["reading_done"]}},{id:"2-C2",site:"tser_pool",map:"river_camp",title:"營火邊的故事",situation:"維斯塔尼人請隊伍喝酒。說書人講起很久以前，一位受傷的王子被他們的祖先所救，從此這個民族可以自由穿過迷霧。有人聽得太認真了。",approaches:[{type:"聽出弦外之音",check:"洞悉 DC 13",outcome:"明白維斯塔尼人之中有人替史特拉德做事，營地裡此刻就有耳目"},{type:"交朋友",check:"表演 DC 12",outcome:"有人私下告訴隊伍瓦拉基外的營地丟了一個女孩"},{type:"買東西和消息",check:"說服 DC 12",outcome:"買到能在霧中認路的護身符，和幾句關於西邊的忠告"}],fail_forward:"隊伍喝多了也說多了。隔天有一隻蝙蝠從營地飛向城堡。",calm:!0},{id:"2-D1",site:"mill",map:"woodland_cottage",title:"賣糕的老太太",situation:"磨坊門口，一位老太太正把熱騰騰的糕裝進小車。她很高興有客人，熱情地請隊伍進來坐，並把通往樓上的門輕輕帶上。",approaches:[{type:"套她的話",check:"洞悉 DC 14",outcome:"看出她的親切底下是打量牲口的眼神"},{type:"假裝買糕",check:"欺瞞 DC 13",outcome:"被請進屋，看見樓梯與上鎖的門"},{type:"繞到後面看",check:"隱匿 DC 13",outcome:"在磨盤邊看見不該出現在麵粉裡的東西"}],fail_forward:"老太太忽然不笑了。她知道隊伍知道了。",foes:[]},{id:"2-D2",site:"mill",map:"woodland_cottage",title:"樓上的籠子",situation:"樓上有兩個小孩被關在木籠裡，還有兩個「女兒」。磨盤在轉。三個女人圍了上來，真面目一張一張露出來。",approaches:[{type:"帶孩子逃",check:"特技 DC 14",outcome:"抱著孩子衝下樓，鬼婆暫時追不上"},{type:"分開她們",check:"奧秘 DC 14",outcome:"知道三個在一起才最危險，設法把其中一個引開"},{type:"打",check:"開戰",outcome:"三個鬼婆聯手，這是一場硬仗"}],fail_forward:"隊伍被趕出了磨坊，孩子還在裡面。莫嘉莎在門口喊：想要回去，可以，拿東西來換。",foes:[["banshee",1],["specter",2]],sets:{success:["children_saved_mill"]}},{id:"2-D3",site:"mill",map:"woodland_cottage",title:"磨坊的帳",situation:"鬼婆願意談。她們要的不多：一個承諾，一件信物，或者別人的孩子。磨坊外，渡鴉成群盤旋，像在等一個結果。",approaches:[{type:"殺光她們",check:"開戰",outcome:"磨坊燒了起來，夢糕從此斷絕"},{type:"談條件",check:"說服 DC 15",outcome:"用一件代價換回孩子與一個消息，鬼婆記住了隊伍的臉"},{type:"讓渡鴉幫忙",check:"馴獸 DC 13",outcome:"鴉群撲進磨坊，鬼婆無法同時施法，局面逆轉"}],fail_forward:"鬼婆帶著她們的東西消失在夜裡。磨坊空了，但她們還會回來。",foes:[["banshee",1],["specter",2]],sets:{success:["hags_slain"],setback:["hags_bargain"]},ifs:[["children_saved_mill","孩子已經救出來，鬼婆是來報復的，不是來談的"]]},{id:"2-E1",site:"svalich_road",map:"grassy_crossroads",title:"路口的絞刑架",situation:"岔路口有一座舊絞刑架。走近時，上面吊著一個人，長得和隊伍裡的某個人一模一樣。再看一眼，繩子是空的。",approaches:[{type:"檢查",check:"調查 DC 13",outcome:"什麼都沒有，但在架下找到一枚刻著鴉閣徽記的舊硬幣"},{type:"穩住同伴",check:"說服 DC 12",outcome:"看見自己的那個人緩了過來，沒有留下陰影"},{type:"不理它繼續走",check:"察覺 DC 13",outcome:"注意到樹林裡有狼跟了一路，卻不靠近"}],fail_forward:"那個畫面留在某個人腦子裡，接下來幾天他睡得很差。",foes:[],calm:!0},{id:"2-E2",site:"svalich_road",map:"grassy_crossroads",title:"黑色的馬車",situation:"霧裡停著一輛沒有車夫的黑馬車，門開著。遠處山崖上，一個披著斗篷的身影騎在馬上，看著隊伍。",approaches:[{type:"上前致意",check:"說服 DC 14",outcome:"史特拉德說了幾句客氣話，表示歡迎，並暗示他什麼都知道"},{type:"拒絕上車",check:"無",outcome:"馬車自己離開了；他笑了笑，掉轉馬頭"},{type:"出手試探",check:"開戰",outcome:"他讓隊伍明白差距，然後毫髮無傷地離去"}],fail_forward:"沒有人說得清楚剛才那一刻發生了什麼。只記得他的目光在某個人身上停得特別久。",foes:[["vampire_spawn",1]],sets:{success:["strahd_met_road"],setback:["strahd_met_road"]},ifs:[["ireena_with_party","他的目光只在伊蕾娜身上，叫了她另一個名字：塔蒂亞娜"],["house_appeased","他提起死亡之屋的獻祭，語氣像在稱讚"]]}]},{act:3,title:"瓦拉基",titleEn:"Vallaki",levelRange:"5",objective:"在一座用笑容撐著的鎮子裡找到立足之地，別讓它在自己手上垮掉",keyEvents:["男爵每週辦一場強迫快樂的慶典","教堂的聖骨失竊","華特夫人在等一個機會","鎮外營地丟了一個女孩"],opening_text:"木牆、尖樁、城門上插著的狼頭。守衛看了隊伍很久才開門。牆內到處貼著告示：烈日慶典，人人參加。「一切都會好的。」",sites:[{id:"vallaki_inn",name:"藍水旅店",map:"wooden_tavern",blurb:"鎮上唯一像樣的旅店，酒是真的，爐火是暖的。屋頂上的渡鴉比客人還多。",secret:"馬提科夫一家是渡鴉化身人，屬於暗中對抗史特拉德的「羽翼守護者」。房客里克塔維奧就是吸血鬼獵人范李希頓。"},{id:"vallaki_church",name:"聖安卓教堂",map:"shadow_cathedral",blurb:"鎮上唯一讓人夜裡敢閉眼的地方。神父看起來很久沒閉眼了。",secret:"祭壇下的聖骨被偷了，教堂已經不再受到庇護。偷的人是祭壇侍童，買主是棺材匠，而棺材匠的閣樓裡住著史特拉德送來的衍體。",ifSkipped:{flag:"church_fell",text:"聖骨沒有找回來，衍體在慶典之夜血洗了教堂。"}},{id:"baron",name:"男爵府",map:"banquet_manor",blurb:"全鎮最大的房子。男爵相信只要每個人都快樂，魔鬼就進不來，不快樂的人會被請去「談談」。",secret:"男爵的兒子維克多在閣樓練習傳送法陣，想逃離巴洛維亞。打手伊澤克從小被惡魔之臂取代了斷臂，一直在找記憶裡的妹妹。"},{id:"wachter",name:"華特宅",map:"woodland_cottage",optional:!0,blurb:"一棟窗簾永遠拉上的老宅。女主人很有禮貌，並且對外地人很有興趣。",rumour:"有人說華特夫人每晚和死去的丈夫說話。",secret:"菲歐娜·華特是史特拉德的忠實臣僕，地下室有一個邪教，她打算推翻男爵。",ifSkipped:{flag:"wachter_rules",text:"沒有人阻止華特夫人，她在混亂中接管了瓦拉基。"}},{id:"vistani_camp",name:"鎮外的維斯塔尼營地",map:"glade_camp",optional:!0,blurb:"鎮外林子裡的營地。首領醉得站不穩，正拿鞭子抽一個年輕人。",rumour:"他們丟了一個小女孩。",secret:"女孩阿拉貝兒被一個瘋了的漁夫擄到贊湖，要把她獻給湖水。",ifSkipped:{flag:"arabelle_lost",text:"沒有人去找那個女孩。"}}],npcs:[{site:"vallaki_inn",name:"烏文·馬提科夫",role:"旅店老闆",description:"話不多，眼睛很亮，對客人的來歷記得一清二楚。",secrets:"渡鴉化身人，羽翼守護者的一員。酒莊是他父親的，父子多年不說話。",voice:"謹慎精明、壓低嗓音但眼神堅定的藍水旅店掌櫃，擦拭酒杯時目光敏銳審視每位茶客。",flaw:"為了保護羽加迪家族（誓言渡鴉）的秘密身份，行事過於保守隱秘，不願冒進。",tactics:"能隨時變身為敏捷的渡鴉飛天偵查，近戰手持獵叉，擅長情報傳遞與暗中策應。",deal:"只要小隊協助解決酒莊斷酒危機並營救其族人，他會正式引薦鴉身人情報網為全隊提供空中耳目。"},{site:"vallaki_inn",name:"里克塔維奧",role:"馬戲團團長",description:"花俏的半精靈，愛說大話，付錢大方。",secrets:"他是魯道夫·范李希頓，鎮外的馬車裡關著一頭劍齒虎，用來獵殺維斯塔尼人。",voice:"滑稽誇張、裝瘋賣傻的嘉年華馬戲團班主腔調，實為傳奇吸血鬼獵人魯道夫·范·里希滕。",flaw:"暮年多疑且自負於一生的狩獵經驗，習慣單打獨鬥，極難對外人放下戒心。",tactics:"偽裝撕下後精通神聖長劍、破邪聖水、銀樁與獵魔陷阱，專克各類亡靈與狼人。",deal:"識破其偽裝並證明小隊並非伯爵密探後，他會卸下偽裝，傾囊相授獵殺史特拉德的弱點筆記。"},{site:"vallaki_church",name:"盧錫安·彼得洛維奇神父",role:"教堂神父",description:"善良、疲憊，相信人到了不該相信的程度。",voice:"虔誠沉靜但滿面愁容的聖安德烈教堂主持，言語間充滿對鎮民安危的深切牽掛。",flaw:"善良但缺乏魄力，過度依賴聖安德烈的遺骨聖物維繫教堂結界，一旦聖骨失竊便束手無策。",tactics:"專注於高階神聖庇護、群體驅散不死生物與大復原術，不善物理搏殺。",deal:"只要替他找回被盜的聖徒遺骨並重新安放於祭壇下，教堂將成為全鎮唯一的永恆安全庇護所。"},{site:"vallaki_church",name:"米利沃伊",role:"掘墓的少年",description:"一個人養著幾個弟妹，手很粗，眼神很兇。",secrets:"他偷了聖骨，賣給棺材匠換錢買吃的。",voice:"倔強粗暴、滿身泥土但眼神慌亂的掘墓少年，說話時目光躲閃不敢正視神父。",flaw:"為了替貧困的年幼弟妹籌措麵包錢而受人利誘，偷盜聖骨後深受良心折磨。",tactics:"揮舞沉重鐵鍬胡亂揮打，身體結實但毫無戰鬥章法，遇險極易驚慌逃竄。",deal:"保證不懲處他並贈予其一袋口糧金幣，他會痛哭流涕交代棺材鋪受指使的全部經過。"},{site:"vallaki_church",name:"亨里克·范德沃特",role:"棺材匠",description:"不開門，不說話，隔著門叫人走開。",secrets:"閣樓的棺材裡躺著一群衍體，他是被逼的。",voice:"膽小如鼠、神經質戰慄的棺材店老闆，說話時牙齒咯咯打顫，滿身木屑味。",flaw:"貪生怕死到了極致，在吸血鬼衍體的恐怖威脅下淪為行屍走肉般的幫凶。",tactics:"毫無戰鬥力，只會抱頭縮進棺材堆裡尖叫求饒。",deal:"只要保證其人身安全，他會毫不猶豫供出二樓棺材裡潛伏著六隻吸血鬼衍體的致命伏擊。"},{site:"baron",name:"瓦爾加斯·瓦拉科維奇男爵",role:"瓦拉基的統治者",description:"神經質，隨身帶著兩條獒犬，把懷疑當成叛亂。",interaction:"稱讚慶典、表現得很快樂，他就把你當朋友。",voice:"亢奮偏執、歇斯底里強調「一切都會好起來！」的獨裁政客尖叫，眼神神經質抽搐。",flaw:"病態迷信歡慶節日能驅逐史特拉德的詛咒，對任何流露悲傷的鎮民施加殘酷鎖具酷刑。",tactics:"躲在數十名城鎮守衛身後督戰，身旁有兇猛獒犬護衛，自身戰鬥力平平。",deal:"假意逢迎其「歡笑節日」理念，能獲得鎮上最高通行特權；若當眾揭露其殘暴，會引發全鎮暴動。"},{site:"baron",name:"伊澤克·史特拉茲尼",role:"男爵的打手",description:"高大，右臂是一條長著爪子的惡魔之臂，能憑空生火。",secrets:"他夢裡的女人是伊蕾娜，他失散多年的親妹妹；他房裡擺滿了照她的樣子做的娃娃。",voice:"殘暴低沉、宛如惡魔喉管磨礪的巨漢咆哮，右臂是一條生著鱗甲與倒鉤的惡魔怪爪。",flaw:"對伊蕾娜懷有病態的執念（實為失散親妹），房間裡堆滿了面容酷似伊蕾娜的詭異木偶。",tactics:"揮舞重型雙刃戰斧劈砍，惡魔怪爪能發射狂暴火焰箭，肉體強悍且嗜血狂暴。",deal:"出示伊蕾娜的信物能令其狂暴出招短暫僵直；若能促成兄妹相認，他甚至願意背叛男爵倒戈護衛。"},{site:"baron",name:"維克多·瓦拉科維奇",role:"男爵的兒子",description:"陰沉的年輕人，把自己關在閣樓。",secrets:"他的傳送法陣試了幾次，每次都把僕人變不見了。",voice:"孤僻傲慢、帶著神經質狂躁的少年法師語調，閣樓中到處是失敗傳送陣留下的焦痕。",flaw:"狂熱盲目自學法術，不惜拿家中僕人當活體實驗品，極度自私且缺乏倫理底線。",tactics:"施展死靈骷髏召喚、電擊爪與迷蹤步，戰鬥時毫不猶豫引爆未完成的法陣玉石俱焚。",deal:"提供一本完整的法術書或高階傳送符文石，他願意交出其私藏的古代魔法卷軸並透露男爵府密道。"},{site:"wachter",name:"菲歐娜·華特夫人",role:"貴族",description:"優雅、冷靜，說話像在下棋。",interaction:"她願意出錢出力幫隊伍，只要他們除掉男爵或伊澤克。",voice:"陰冷優雅、字正腔圓的貴族遺孀腔調，言談間充滿了推翻男爵暴政的政治野心。",flaw:"表面是反抗男爵的清流，暗中早已向史特拉德宣誓效忠並在地下室豢養邪教徒。",tactics:"驅使狂熱邪教徒組成死士陣線，施展中階死靈法術，擅長在政治動亂中借刀殺人。",deal:"只要小隊協助其除掉男爵瓦爾加斯，她願意接管瓦拉基鎮並為小隊提供全鎮庇護與金幣酬勞。"},{site:"vistani_camp",name:"盧瓦希",role:"營地首領",description:"阿拉貝兒的父親，醉得一塌糊塗。",voice:"醉眼惺忪、酒氣熏天的維斯塔尼營地首領，說話時動輒打著酒嗝，看似頹廢昏庸。",flaw:"沉溺於烈酒無法自拔，對女兒阿拉貝拉的失蹤感到痛徹心扉卻無能為力。",tactics:"拔出彎刀發動醉拳連環斬擊，精通維斯塔尼詛咒，在酒精麻醉下悍不畏死。",deal:"只要將落水被困的女兒阿拉貝拉活著救回營地，他會哭著奉上族傳寶庫鑰匙並立誓為盟友。"},{site:"vistani_camp",name:"亞里加爾",role:"首領的弟弟",description:"清醒、客氣、樂於助人。",secrets:"他是史特拉德的眼線，隨時回報隊伍的行蹤。",voice:"陰鷙銳利、滿面殺氣的冷血刺客嗓音，說話簡短且總是撫摸腰間的淬毒匕首。",flaw:"史特拉德安插在維斯塔尼營地中的忠實眼線，極度迷信伯爵的無敵力量。",tactics:"擅長暗影隱匿與極限跳躍刺殺，雙持毒刃專挑後排布甲法師下手，身法如鬼魅。",deal:"唯利是圖的亡命之徒；若能展現出絕對壓倒性的戰力並繳獲其密信，他會權衡利弊暫時出賣伯爵動向。"}],encounters:["吸血鬼衍體","守衛","邪教徒","邪教狂熱者","野狼","強盜"],treasures:["聖安卓的遺骨","男爵的赦令","維斯塔尼人的贈禮","范李希頓的日記"],endCondition:"瓦拉基的局面定了下來，不論是誰坐在男爵府裡",strategic_nodes:[{id:"3-A1",site:"vallaki_inn",map:"wooden_tavern",title:"有酒的地方",situation:"旅店裡有真正的笑聲，雖然不大。老闆娘上菜時多看了隊伍兩眼。靠窗一個衣著花俏的半精靈正在向全場吹噓他的馬戲團。",approaches:[{type:"向老闆打聽",check:"說服 DC 12",outcome:"烏文說出鎮上的幾股勢力，並提到酒莊的酒遲了"},{type:"注意那個半精靈",check:"洞悉 DC 15",outcome:"他的浮誇是演的，他在觀察每一個人"},{type:"安頓下來",check:"察覺 DC 12",outcome:"發現屋頂的渡鴉在輪流盯著隊伍的窗戶"}],fail_forward:"隊伍在旅店裡說了太多。當晚男爵府就知道鎮上來了外地人。",calm:!0,sets:{success:["keepers_friend"]},ifs:[["ireena_with_party","伊蕾娜在這裡第一次睡了一個整夜；烏文認得她頸上的傷是什麼"],["hags_slain","渡鴉已經把磨坊的事帶到了，馬提科夫一家對隊伍格外客氣"]]},{id:"3-A2",site:"vallaki_inn",map:"night_alley",title:"鎮外的馬車",situation:"鎮外路邊停著一輛上了三道鎖的馬戲團馬車。車身在晃。裡面有東西在撞，聲音很大。",approaches:[{type:"不開它",check:"洞悉 DC 12",outcome:"判斷這是有人刻意藏起來的武器，回去找主人談"},{type:"撬鎖",check:"巧手 DC 15",outcome:"看見裡面是一頭餓得發狂的劍齒虎，及時關上"},{type:"偷看主人的房間",check:"隱匿 DC 14",outcome:"找到一本日記，寫的是一個獵人一生的悔恨"}],fail_forward:"車門開了。一頭巨獸衝進夜色，鎮上亂成一團，而牠的主人知道是誰幹的。",foes:[["owlbear",1]]},{id:"3-A3",site:"vallaki_inn",map:"wooden_tavern",title:"面具底下",situation:"里克塔維奧請隊伍喝酒，話題繞了三圈，最後問了一個他真正想問的問題：你們打算拿史特拉德怎麼辦？",approaches:[{type:"坦白",check:"說服 DC 13",outcome:"他卸下偽裝，承認自己是誰，並說出他知道的弱點"},{type:"點破他",check:"洞悉 DC 14",outcome:"他沉默了一會，說很久沒有人看穿他了"},{type:"質問劍齒虎的事",check:"威嚇 DC 14",outcome:"他承認自己恨維斯塔尼人恨錯了，卻停不下來"}],fail_forward:"他笑著打了個哈哈，付了酒錢離開。隔天他的房間空了。",calm:!0,sets:{success:["rictavio_trusts"]},ifs:[["arabelle_saved","他聽說隊伍救了一個維斯塔尼女孩，神情複雜"]]},{id:"3-B1",site:"vallaki_church",map:"shadow_cathedral",title:"空了的祭壇",situation:"神父壓低聲音告訴隊伍：祭壇下的聖骨不見了。沒有它，這座教堂只是一棟木頭房子。他不敢讓任何人知道。",approaches:[{type:"問誰知道聖骨",check:"調查 DC 12",outcome:"知道的只有神父、侍童和掘墓的米利沃伊"},{type:"檢查祭壇",check:"調查 DC 13",outcome:"撬痕很新，是不熟練的人用鏟子幹的"},{type:"安撫神父",check:"說服 DC 11",outcome:"他想起曾對侍童說溜嘴"}],fail_forward:"神父慌了，開始在講道時暗示。消息在鎮上傳開，不該知道的人也知道了。",calm:!0},{id:"3-B2",site:"vallaki_church",map:"night_alley",title:"掘墓的少年",situation:"米利沃伊在墓地裡挖一個新坑。他看見隊伍朝他走來，握緊了鏟子。他身後的小屋裡有幾個孩子在看。",approaches:[{type:"好好跟他說",check:"說服 DC 13",outcome:"他哭了，說是棺材匠給了他錢，他只是要養弟妹"},{type:"嚇他",check:"威嚇 DC 12",outcome:"他招了，但從此恨上了隊伍"},{type:"先幫他一把",check:"無",outcome:"留下食物或錢；他主動說出一切，還願意帶路"}],fail_forward:"少年跑了。隊伍只能從他丟下的錢袋上的木屑猜出去向，晚了半天。",calm:!0},{id:"3-B3",site:"vallaki_church",map:"harbour_fort",title:"棺材匠的閣樓",situation:"棺材舖的門窗釘死了。亨里克隔著門求隊伍離開。樓上的地板在響，不只一個人的重量。",approaches:[{type:"白天進去",check:"調查 DC 12",outcome:"趁衍體沉睡時找到聖骨，並看清閣樓裡有幾口棺材"},{type:"逼棺材匠說",check:"威嚇 DC 13",outcome:"他說出聖骨藏在樓上他的衣櫃裡，還有那些「房客」"},{type:"夜裡硬闖",check:"開戰",outcome:"衍體全醒著"}],fail_forward:"隊伍拿到了聖骨，也驚醒了閣樓。衍體沒有追出來，牠們在等一個更好的晚上。",foes:[["vampire_spawn",2]]},{id:"3-B4",site:"vallaki_church",map:"shadow_cathedral",title:"聖安卓之夜",tactical:{"scenarioId":"shadow_cathedral","heroFormation":"center","foeFormation":"surround","ambushMode":"foe_surprise","lighting":"dark","objectiveName":"重歸聖安卓聖骸護住教堂","allies":[{"name":"盧西安神父","role":"vip"}],"interactables":[{"kind":"crystal","name":"聖安卓聖骸祭壇","dc":14,"rewardEffect":"aoe_holy_burst","rewardDesc":"聖骸歸位！教堂迸發刺目聖光灼傷所有吸血鬼！"}],"script":{"missionGoal":"護住盧西安神父並將聖骸放回聖壇驅散血族","opening":[{"speaker":"吸血鬼衍體","side":"foe","line":"今晚的瓦拉齊教堂，不會有任何禱告聲響起！"},{"speaker":"我方隊長","side":"hero","line":"護住神父！快把聖骸送回中央祭壇啟動聖光結界！"}],"propLine":{"speaker":"我方隊員","side":"hero","line":"聖骸歸位了！聖光正在把這群血族逼退！"}}},situation:"衍體還是來了，挑的是全鎮都在慶典上的時候。牠們穿過街道，直奔教堂。",approaches:[{type:"守住教堂",check:"開戰",outcome:"聖骨歸位的教堂裡，衍體寸步難行"},{type:"把人撤出去",check:"說服 DC 14",outcome:"教堂保不住，但裡面的人活了下來"},{type:"先下手",check:"隱匿 DC 14",outcome:"在牠們出發前燒了棺材舖的閣樓"}],fail_forward:"教堂的門被撞開。神父死在祭壇前，鎮民再也沒有一個晚上敢閉眼。",foes:[["vampire_spawn",3]],sets:{success:["bones_returned"],setback:["church_fell"]},ifs:[["rictavio_trusts","范李希頓帶著木樁出現在教堂門口"],["keepers_friend","成群的渡鴉撲向衍體的臉"]]},{id:"3-C1",site:"baron",map:"banquet_manor",title:"一切都會好的",situation:"男爵親自接見隊伍，身邊站著伊澤克和兩條獒犬。他問的第一個問題是：你們快樂嗎？",approaches:[{type:"順著他",check:"欺瞞 DC 12",outcome:"男爵很滿意，邀隊伍參加慶典並給了通行的方便"},{type:"講道理",check:"說服 DC 15",outcome:"他聽進了一點，至少沒有把人關起來"},{type:"直說這很荒謬",check:"無",outcome:"隊伍被請去「談談」，或者直接被趕出府"}],fail_forward:"男爵認定隊伍是來搗亂的。從這天起，隊伍身後總有兩個守衛。",calm:!0,sets:{success:["baron_ally"],setback:["baron_enemy"]},ifs:[["ireena_with_party","伊澤克盯著伊蕾娜看，一句話也沒說，手在發抖"]]},{id:"3-C2",site:"baron",map:"banquet_manor",title:"閣樓上的兒子",situation:"僕人們不肯上三樓。門上畫著骷髏，門後有唸咒的聲音，還有一隻沒有身體的貓骨架走來走去。",approaches:[{type:"敲門",check:"說服 DC 14",outcome:"維克多讓隊伍進來，展示他想逃離這裡的法陣"},{type:"看懂法陣",check:"奧秘 DC 14",outcome:"看出它還缺一筆，補上之前誰踏進去都會消失"},{type:"問僕人",check:"調查 DC 12",outcome:"知道已經有兩個僕人不見了"}],fail_forward:"法陣亮了一下。一個隊員的半邊身體麻了一整天，維克多則對外人更加戒備。",foes:[],calm:!0},{id:"3-C3",site:"baron",map:"banquet_manor",title:"伊澤克的房間",situation:"伊澤克的房裡擺滿了娃娃。幾十個，全是同一張臉，紅頭髮。做娃娃的匠人說，他每個月都來訂一個，每次都說不夠像。",approaches:[{type:"找匠人問",check:"調查 DC 12",outcome:"知道伊澤克小時候在狼群襲擊中失去了手臂和妹妹"},{type:"當面問他",check:"洞悉 DC 14",outcome:"他說他只想知道她是不是還活著"},{type:"讓兄妹相認",check:"說服 DC 15",outcome:"伊澤克跪了下來；他從此只聽一個人的話"}],fail_forward:"伊澤克發現有人進過他的房間。他沒有聲張，只是開始跟蹤隊伍。",calm:!0,sets:{success:["izek_knows_ireena"]},ifs:[["!ireena_with_party","伊蕾娜不在這裡。隊伍認得那張臉，可以決定要不要告訴他她在哪"],["ireena_with_party","伊蕾娜自己看見了那些娃娃"]]},{id:"3-C4",site:"baron",map:"indoor_market",title:"烈日慶典",situation:"廣場上搭起了一顆柳條編的大太陽。下起雨來，火點不著。有個守衛笑了一聲。男爵下令把他綁在馬後拖行。",approaches:[{type:"出面阻止",check:"說服 DC 15",outcome:"男爵下不了台，但人群第一次站在了外地人這邊"},{type:"暗中點火",check:"巧手 DC 13",outcome:"太陽燒了起來，男爵找到了台階，事情過去了"},{type:"袖手旁觀",check:"無",outcome:"守衛被拖過廣場；人群安靜得可怕"}],fail_forward:"場面失控。有人丟了石頭，守衛拔了劍，慶典成了暴動的開頭。",foes:[["guard",4]],sets:{success:[],setback:["baron_deposed"]},ifs:[["baron_enemy","男爵當眾指著隊伍說，這就是不快樂的人帶來的"],["izek_knows_ireena","伊澤克沒有執行男爵的命令，他在看伊蕾娜的眼色"],["wachter_exposed","華特夫人的事已經傳開，鎮民知道這座鎮上不只男爵一個人在說謊"]]},{id:"3-D1",site:"wachter",map:"woodland_cottage",title:"夫人的茶",situation:"華特夫人請隊伍喝茶。她對男爵的評價很直接：一個讓全鎮陪他發瘋的蠢人。她有一個提議。",approaches:[{type:"聽完再說",check:"洞悉 DC 14",outcome:"聽出她真正效忠的是誰"},{type:"假意答應",check:"欺瞞 DC 14",outcome:"取得她的信任和一筆錢，還有進出宅子的自由"},{type:"拒絕",check:"無",outcome:"她微笑送客，並記下了這筆帳"}],fail_forward:"茶裡沒有毒。但隊伍離開時，有人發現自己說出了本來不打算說的事。",calm:!0,ifs:[["baron_enemy","她知道男爵在通緝隊伍，提議更加大方"],["baron_ally","她知道隊伍是男爵的客人，說話滴水不漏"]]},{id:"3-D2",site:"wachter",map:"shadow_cathedral",title:"地下室的聚會",situation:"宅子的地下室有一圈椅子、一個畫在地上的陣，和一群在白天對隊伍點頭微笑的鎮民。樓上的臥房裡，夫人正在跟床上的人說晚安。那個人死了很久了。",approaches:[{type:"蒐集證據",check:"隱匿 DC 14",outcome:"帶走名冊與書信，足以讓她身敗名裂"},{type:"當場打斷",check:"開戰",outcome:"邪教徒四散，夫人從密道離開"},{type:"公開揭發",check:"說服 DC 14",outcome:"需要男爵或神父出面，鎮民才會相信"}],fail_forward:"隊伍被發現了。夫人沒有動手，她只是讓全鎮都知道有外地人夜闖民宅。",foes:[["cult_fanatic",1],["cultist",4]],sets:{success:["wachter_exposed"],setback:["wachter_rules"]}},{id:"3-D3",site:"wachter",map:"stone_streets",title:"誰來管這座鎮",situation:"瓦拉基撐不住兩個主人。男爵、夫人，或者誰都不要。鎮民在等，而他們看的是隊伍。",approaches:[{type:"保住男爵",check:"說服 DC 14",outcome:"他留了下來，欠隊伍一個大人情，慶典照舊"},{type:"讓鎮民自己選",check:"說服 DC 16",outcome:"一個沒有人預料到的人選站了出來；這座鎮第一次自己做了決定"},{type:"扶植夫人",check:"無",outcome:"秩序很快恢復，代價是史特拉德在鎮裡有了一雙手"}],fail_forward:"火把、石頭、被拖出府的男爵。等一切安靜下來，坐在男爵府裡的是華特夫人。",foes:[["guard",3],["bandit",3]],sets:{success:[],setback:["wachter_rules","baron_deposed"]},ifs:[["wachter_exposed","夫人已經失勢，這個局面是男爵與憤怒的鎮民之間的事"],["church_fell","教堂的事讓鎮民不再相信任何人的保證"]]},{id:"3-E1",site:"vistani_camp",map:"glade_camp",title:"鞭子與酒",situation:"首領盧瓦希醉醺醺地鞭打一個年輕人，罵他沒看好自己的女兒。弟弟亞里加爾在一旁勸，同時把隊伍的長相記了下來。",approaches:[{type:"問清楚",check:"說服 DC 12",outcome:"女孩阿拉貝兒昨天在湖邊不見了，有人看見一個漁夫"},{type:"讓他停手",check:"威嚇 DC 13",outcome:"盧瓦希清醒了一點，求隊伍幫忙"},{type:"留意弟弟",check:"洞悉 DC 15",outcome:"看出亞里加爾問的問題太有條理"}],fail_forward:"盧瓦希把氣出在外地人身上。隊伍被趕出營地，只聽到了「湖」這個字。",calm:!0},{id:"3-E2",site:"vistani_camp",map:"woodland_lake",title:"贊湖上的小船",situation:"湖心有一條小船。船上的男人把一個麻袋舉過頭頂，對著湖水喃喃自語。麻袋在動。",approaches:[{type:"游過去",check:"運動 DC 14",outcome:"在麻袋沉下去之前抓住了它"},{type:"喊住他",check:"說服 DC 15",outcome:"漁夫猶豫了；他說湖裡很久沒有魚了，湖要吃東西"},{type:"從岸上出手",check:"察覺 DC 14",outcome:"一擊讓他鬆了手，還得有人下水撈"}],fail_forward:"麻袋沉了下去。有人跳進冰冷的湖水，撈上來時女孩已經沒有呼吸，救不救得回來要看運氣和手藝。",foes:[["bandit",1]],sets:{success:["arabelle_saved"],setback:["arabelle_lost"]}},{id:"3-E3",site:"vistani_camp",map:"glade_camp",title:"營地的回禮",situation:"隊伍回到營地。整個營地的人都站了起來。",approaches:[{type:"接受謝意",check:"無",outcome:"盧瓦希讓隊伍從寶物車裡挑一樣東西，並說維斯塔尼人會記得"},{type:"要消息不要禮物",check:"說服 DC 12",outcome:"得知史特拉德在維斯塔尼人之中有耳目，以及通往城堡的另一條路"},{type:"點出亞里加爾",check:"洞悉 DC 15",outcome:"首領不肯相信，但從此留了心"}],fail_forward:"營地裡沒有人說話。盧瓦希看著湖的方向，揮手要外地人走。",calm:!0,ifs:[["arabelle_saved","阿拉貝兒抱住救她的人，在他耳邊說了一句關於他未來的話"],["arabelle_lost","隊伍帶回來的是壞消息；這個局面沒有謝禮，只有一個父親"]]}]},{act:4,title:"酒與渡鴉",titleEn:"Wine and Ravens",levelRange:"6",objective:"西邊的酒斷了。查出原因，並決定要為這片土地最後一點歡樂付出多少",keyEvents:["酒莊被德魯伊與枯萎怪佔據","保護葡萄園的寶石被偷","昨日山丘上有東西要醒來","湖上的塔有主人留下的陷阱"],opening_text:"過了瓦拉基，路往西進入更深的林子。沿路的旅店都在說同一件事：酒莊的馬車已經遲了兩個星期。在巴洛維亞，酒是人們還能笑得出來的少數理由之一。",sites:[{id:"winery",name:"魔法師之酒莊",map:"farmstead",blurb:"霧中的葡萄園和一棟石造大屋。葡萄藤在動，那不是風。",secret:"酒莊靠三顆有魔力的寶石讓葡萄生長。一顆多年前就丟了，一顆被德魯伊帶上昨日山丘，一顆被芭芭·莉薩迦拿去柏瑞茲。馬提科夫一家是渡鴉化身人。",ifSkipped:{flag:"winery_burned",text:"沒有人去酒莊，枯萎怪把葡萄園毀了。"}},{id:"yester_hill",name:"昨日山丘",map:"ruined_keep",blurb:"一座光禿禿的山丘，頂上有一圈立石和一棵流著紅色樹汁的老樹。站在這裡可以看見霧牆外一座不存在的城市。",secret:"崇拜史特拉德的德魯伊要用寶石喚醒一尊巨大的枯萎怪，讓它踏平酒莊。那棵樹是枯萎怪的源頭。",needs:"winery_saved"},{id:"tower",name:"范李希頓的塔",map:"blue_tower",optional:!0,ifSkipped:{text:"湖中的塔沒有人去。在那附近紮營的女人沒有遇到隊伍，獨自往北去了。"},blurb:"湖中小島上一座快要塌的石塔。門上有一道會發光的符文，門前的地上有幾具燒焦的狼屍。",rumour:"有人看過一個女人在塔附近紮營。",secret:"塔是范李希頓的藏身處。門上的陷阱要用特定的動作解除；塔本身撐不住一次大的爆炸。"},{id:"werewolf_den",name:"狼人巢穴",map:"bear_cavern",optional:!0,blurb:"山壁上的洞穴，洞口掛著獸骨。夜裡的嚎叫都是從這個方向來的。",rumour:"村子丟的孩子，有些是被狼叼走的。",secret:"首領基里爾擄來孩子逼他們互相殘殺，活下來的才配成為狼人。前首領埃米爾被關在鴉閣城堡，他的妻子祖萊卡在等一個機會。",ifSkipped:{flag:"werewolves_hostile",text:"狼人繼續擄走孩子。"}}],npcs:[{site:"winery",name:"達維安·馬提科夫",role:"酒莊主人",description:"固執的老人，帶著全家躲在林子裡，看著自己的家被佔。",secrets:"渡鴉化身人，羽翼守護者的領袖。他不信任外人，除非他們證明自己。",voice:"頑固剛烈、如老樹樁般風霜刻骨的巫師之泉酒莊老族長嗓音，長袍下透著羽毛氣息。",flaw:"脾氣臭硬固執，與長子阿德里安常年心存芥蒂，對丟失釀酒魔法寶石自責不已。",tactics:"化身大型渡鴉從高空俯衝抓啄，手持草叉近身肉搏，指揮渡鴉群啄瞎狂暴德魯伊的雙眼。",deal:"只要奪回被德魯伊與狂暴樹怪霸佔的酒莊，他願重啟巫師之泉酒桶供應，並引薦全境渡鴉密探。"},{site:"winery",name:"阿德里安·馬提科夫",role:"長子",description:"想立刻打回去，被父親攔著。",voice:"熱情坦誠、富有冒險精神的年輕渡鴉人長子嗓音，渴望贏得老父親的認可。",flaw:"缺乏老族長的沉穩，在面對狂暴樹怪大軍時容易衝動冒進陷入重圍。",tactics:"空中高速盤旋投擲燃燒瓶，配合隊友撕裂敵軍陣型，擅長偵察與快速穿插。",deal:"協助其修復家族裂痕並奪回聖寶，他會主動請纓化身渡鴉全程擔任小隊的空中哨兵。"},{site:"yester_hill",name:"德魯伊首領",role:"森林之民的祭司",description:"披著鹿骨與獸皮，相信史特拉德就是這片土地本身。",voice:"瘋癲嘶吼、帶著野獸般咆哮的荒野祭司嗓音，身披染血獸皮，頭戴鹿角白骨冠。",flaw:"狂熱崇拜史特拉德為「大地的古老主宰」，將奪得的魔法綠寶石視為至高神物。",tactics:"驅使狂暴樹怪與枯萎怪大軍合圍，召喚毒荊棘叢生與落雷術，並變身兇暴棕熊衝撞。",deal:"狂熱的自然異端絕不言和；唯有斬殺首領並奪回被其污染的魔法寶石，方能瓦解枯萎大軍。"},{site:"tower",name:"艾茲梅瑞妲·達瓦尼爾",role:"吸血鬼獵人",description:"維斯塔尼人，一條腿是義肢，帶著整車的炸藥。她在找她的老師。",secrets:"她是范李希頓的學生，和他鬧翻後獨自來獵殺史特拉德。",voice:"灑脫不羈、語調飛揚且充滿戰鬥激情的維斯塔尼女獵魔人，右腿義肢踏地沉穩有力。",flaw:"好勝心極強且行事魯莽衝動，為了向導師范·里希滕證明自己常孤身犯險。",tactics:"雙持短劍與精鋼獵斧，精通魔法飛彈、火球術與淬毒投刃，戰鬥風格狂野華麗。",deal:"只要小隊展現出獵殺吸血鬼的真才實學，她會豪邁大笑著加入隊伍，成為最強近戰奧術搭檔。"},{site:"werewolf_den",name:"基里爾·史托亞諾維奇",role:"狼人首領",description:"把殘忍當成紀律。",voice:"粗暴殘虐、伴隨狼喉咆哮的狼人族長狂吼，將活人獵物視為供狼崽撕咬的肉塊。",flaw:"殘暴嗜殺且依仗史特拉德的恩寵，在狼群中推行弱肉強食，引發部分族人不滿。",tactics:"滿月變身巨型狂暴狼人，肉體自癒能力驚人，率領狼群實施撕咬、撲倒與拖拽圍殺。",deal:"兇殘的狼人首領拒絕任何平等談判；唯有出示銀質武器並斬殺其頭狼，才能徹底擊潰其狼群。"},{site:"werewolf_den",name:"祖萊卡·托倫斯卡",role:"前首領之妻",description:"還穿著人的衣服，守著丈夫留下的位置。",interaction:"誰能帶回埃米爾的消息，她就幫誰。",voice:"哀怨隱忍、自牙縫中透出仇恨的雌狼人低語，頸部佩戴著被囚丈夫埃米爾的毛皮信物。",flaw:"深愛被史特拉德關入鴉閣堡地牢的丈夫埃米爾，對篡位者基里爾懷有滔天仇恨。",tactics:"擅長陰影伏擊與喉管撲殺，在遭遇銀質武器時會敏捷後躍避開致命鋒芒。",deal:"承諾前往鴉閣堡地牢解救其丈夫埃米爾，她願在狼人洞穴中倒戈相向，協助小隊除掉基里爾。"}],encounters:["野狼","恐狼","侍僧","邪教狂熱者","巨魔","梟熊"],treasures:["紫葡萄籽釀的陳年酒","酒莊的寶石","范李希頓的筆記","銀製武器"],endCondition:"西邊的事有了結果，酒莊或者保住了，或者沒有",strategic_nodes:[{id:"4-A1",site:"winery",map:"bright_trail",title:"林子裡的一家人",situation:"還沒看見酒莊，先被人攔下了。一個老人帶著兒孫躲在樹林裡，身上披著斗篷，渾身濕透。他們的家就在霧的那一頭。",approaches:[{type:"取得信任",check:"說服 DC 13",outcome:"達維安說出德魯伊與枯萎怪的數量，以及屋裡的格局"},{type:"提旅店的事",check:"無",outcome:"知道隊伍是烏文的朋友後，老人的態度軟了下來"},{type:"觀察他們",check:"洞悉 DC 14",outcome:"注意到這家人說話時，樹上的渡鴉全都靜了下來"}],fail_forward:"老人不肯多說，只說想送死就自己去。隊伍只能自己摸進去。",calm:!0,ifs:[["keepers_friend","渡鴉早就把隊伍的事帶到了；達維安直接把他們當成自己人"],["hags_slain","達維安聽說過磨坊的事，主動上前握手"]]},{id:"4-A2",site:"winery",map:"farmstead",title:"葡萄園",situation:"葡萄藤之間站著幾十個用樹枝和荊棘紮成的人形。它們在風停的時候動。屋頂上有個披著獸皮的人在指揮。",approaches:[{type:"放火",check:"生存 DC 13",outcome:"火逼退了外圍的枯萎怪，但得小心別燒到葡萄"},{type:"潛進屋",check:"隱匿 DC 14",outcome:"避開園子，從酒窖的運貨門進去"},{type:"強攻",check:"開戰",outcome:"枯萎怪一波一波湧上來"}],fail_forward:"隊伍被逼退到林邊。園子裡的東西比早上更多了。",foes:[["wolf",3],["acolyte",2]]},{id:"4-A3",site:"winery",map:"woodland_cottage",title:"酒窖與發酵桶",situation:"德魯伊在酒窖裡，往最大的那一桶酒裡倒東西。地上的坑是空的，原本埋在那裡的東西被挖走了。",approaches:[{type:"阻止下毒",check:"特技 DC 14",outcome:"保住了大部分的酒"},{type:"留活口",check:"威嚇 DC 14",outcome:"德魯伊說寶石已經送上昨日山丘，儀式就在今晚"},{type:"全部解決",check:"開戰",outcome:"酒窖清空了，但沒有人能問話"}],fail_forward:"最大的那桶酒毀了。德魯伊從運貨門退走，往山丘的方向。",foes:[["cult_fanatic",1],["acolyte",2]],sets:{success:["winery_saved"],setback:["winery_saved"]}},{id:"4-A4",site:"winery",map:"farmstead",title:"三顆寶石",situation:"馬提科夫一家回到屋裡。老人終於說了實話：葡萄園靠三顆寶石活著，現在一顆都不在了。他還說了另一件事，關於他們一家真正是什麼。",approaches:[{type:"答應去找",check:"無",outcome:"達維安把隊伍當成盟友，送上陳酒與一個承諾"},{type:"問渡鴉的事",check:"洞悉 DC 12",outcome:"他承認了羽翼守護者的存在，並說出他們在各地的眼線"},{type:"談父子的事",check:"說服 DC 14",outcome:"達維安答應寫一封信給瓦拉基的兒子"}],fail_forward:"老人沒有全說。他謝過隊伍，但有些話留到他們從山丘回來再講。",calm:!0,sets:{success:["keepers_friend"]}},{id:"4-B1",site:"yester_hill",map:"ruined_keep",title:"山丘上的石圈",situation:"德魯伊圍著一尊用整棵樹紮成的巨大人形跳舞。它的胸口嵌著一顆發綠光的寶石。霧牆之外，隱約有一座城市的燈火。",approaches:[{type:"搶寶石",check:"特技 DC 15",outcome:"在儀式完成前把寶石挖出來，巨像沒有醒"},{type:"打斷儀式",check:"開戰",outcome:"德魯伊與野蠻人一起撲上來"},{type:"等時機",check:"隱匿 DC 14",outcome:"看清儀式的步驟，知道哪一刻下手最有效"}],fail_forward:"巨像睜開了眼睛。它站起來，朝酒莊的方向邁出第一步。",foes:[["cult_fanatic",1],["acolyte",3]],sets:{success:["gem_recovered"]}},{id:"4-B2",site:"yester_hill",map:"ruined_keep",title:"巨木枯萎怪",tactical:{"scenarioId":"ruined_keep","heroFormation":"bottom","foeFormation":"top","ambushMode":"normal","weather":"lightning_storm","objectiveName":"斬斷古爾斯魔樹的血脈根須","namedFoes":[{"template":"troll","name":"巨木枯萎怪","isBoss":true}],"interactables":[{"kind":"oil_barrel","name":"滲血魔樹枯枝堆","dc":12,"rewardEffect":"aoe_holy_burst","rewardDesc":"烈焰引燃魔樹枯枝，阻斷枯萎怪的再生之力！"}],"script":{"missionGoal":"在雷暴石圈中斬殺巨木枯萎怪，終結邪惡儀式","opening":[{"speaker":"我方隊長","side":"hero","line":"用火攻！別讓那頭巨木怪物靠血藤繼續再生！"}],"triggers":{"foeHalfHp":{"speaker":"我方隊員","side":"hero","line":"它的樹皮裂開了，趁現在點燃枯枝集中斬首！"}}}},situation:"它有三層樓高，每一步都讓地面震動。它不看隊伍，它只往酒莊走。",approaches:[{type:"攻擊胸口",check:"開戰",outcome:"寶石是它的心臟"},{type:"燒它",check:"生存 DC 14",outcome:"火讓它慢了下來，也讓它發狂"},{type:"引它走錯路",check:"自然 DC 15",outcome:"把它引向懸崖或沼澤"}],fail_forward:"它走到了酒莊。隊伍一路追著打，最後在葡萄園裡把它放倒，半個園子已經毀了。",foes:[["troll",1]],sets:{success:["wintersplinter_fell"],setback:["winery_burned"]},ifs:[["gem_recovered","寶石已經被挖走，巨像沒有醒，這個局面是殘餘的德魯伊拼死反撲"],["keepers_friend","成群的渡鴉啄它的眼睛，替隊伍爭取時間"]]},{id:"4-B3",site:"yester_hill",map:"agatha_grove",title:"流血的樹",situation:"山丘另一側有一棵老樹，樹幹上插著一把斧頭，傷口流出像血的樹汁。周圍的土裡不斷有小小的枯萎怪爬出來。",approaches:[{type:"砍倒它",check:"運動 DC 14",outcome:"樹倒了，枯萎怪不再出現"},{type:"淨化它",check:"宗教 DC 15",outcome:"樹汁變清了，樹活了下來，不再生出怪物"},{type:"研究它",check:"奧秘 DC 13",outcome:"知道它與史特拉德的血有關，取走一截可以做成對他有用的東西"}],fail_forward:"樹沒有倒。隊伍離開時，土裡又有東西在動。",foes:[["wolf",2]]},{id:"4-C1",site:"tower",map:"blue_tower",title:"門上的符文",situation:"塔門上刻著一圈發光的字和幾個小人的圖案，擺著奇怪的姿勢。門前的狼屍燒得只剩骨頭。",approaches:[{type:"照圖案做",check:"表演 DC 12",outcome:"跟著小人的動作跳了一段，門開了"},{type:"解除它",check:"奧秘 DC 15",outcome:"找到符文的破綻"},{type:"硬開",check:"無",outcome:"閃電從門上炸開"}],fail_forward:"第一個碰門的人被閃電打飛出去。門還是開了，是被炸開的。",foes:[],calm:!0},{id:"4-C2",site:"tower",map:"blue_tower",title:"獵人的房間",situation:"塔頂是一個人住了很久的地方：地圖、筆記、一口上鎖的箱子，和一顆泡在罐子裡的頭。筆記的最後一頁寫著，他要去瓦拉基，換一個名字。",approaches:[{type:"讀筆記",check:"調查 DC 12",outcome:"知道了范李希頓的偽裝、他對維斯塔尼人的仇恨和他的愧疚"},{type:"開箱子",check:"巧手 DC 15",outcome:"箱子有機關，處理得當就能安全打開"},{type:"問罐子裡的頭",check:"奧秘 DC 14",outcome:"它還能回答幾個問題"}],fail_forward:"箱子的機關動了。隊伍有幾秒鐘可以跑。",foes:[],calm:!0,sets:{setback:["tower_destroyed"]},ifs:[["rictavio_trusts","隊伍早就知道這裡是誰的；筆記補上了他沒說出口的部分"]]},{id:"4-C3",site:"tower",map:"river_camp",title:"另一個獵人",situation:"塔外有人。一個女人靠著她的馬車，手裡的十字弓指著隊伍，車上裝的東西足夠把整座島炸平。",approaches:[{type:"說明來意",check:"說服 DC 13",outcome:"艾茲梅瑞妲放下武器，交換彼此知道的事"},{type:"提到她的老師",check:"洞悉 DC 13",outcome:"她嘴上不饒人，但立刻問他在哪"},{type:"比試",check:"開戰",outcome:"她試試隊伍的身手，點到為止"}],fail_forward:"她把隊伍當成史特拉德的人。馬車衝了出去，留下一句話：別跟來。",foes:[],calm:!0,sets:{success:["ezmerelda_ally"]},ifs:[["tower_destroyed","她是被爆炸聲引來的，劈頭就問是誰炸了她老師的塔"],["rictavio_trusts","隊伍可以告訴她范李希頓在瓦拉基"]]},{id:"4-D1",site:"werewolf_den",map:"bear_cavern",title:"洞口",situation:"洞口有兩個守衛，半人半狼，正在分一隻鹿。洞裡傳來小孩的哭聲。",approaches:[{type:"摸進去",check:"隱匿 DC 15",outcome:"避開守衛，看見洞裡的佈局和關孩子的地方"},{type:"假裝投靠",check:"欺瞞 DC 15",outcome:"被帶進去見首領"},{type:"殺進去",check:"開戰",outcome:"嚎叫聲驚動了整個巢穴"}],fail_forward:"隊伍被發現了。狼人沒有立刻撲上來，牠們在笑：獵物自己送上門。",foes:[["dire_wolf",2],["wolf",2]]},{id:"4-D2",site:"werewolf_den",map:"bone_den",title:"孩子的坑",situation:"洞穴深處有一個坑，坑裡關著幾個孩子，每人手裡被塞了一把刀。祖萊卡站在坑邊，沒有阻止，也沒有看。",approaches:[{type:"跟祖萊卡談",check:"說服 DC 14",outcome:"她說她丈夫埃米爾絕不會做這種事，他被史特拉德關在城堡裡"},{type:"帶孩子走",check:"特技 DC 14",outcome:"趁狼群出獵時把孩子一個一個拉上來"},{type:"挑戰首領",check:"開戰",outcome:"照狼的規矩，贏的人說了算"}],fail_forward:"孩子救出了一半。剩下的被狼人拖進更深的洞裡。",foes:[["dire_wolf",2],["bugbear",1]],sets:{setback:["werewolves_hostile"]}},{id:"4-D3",site:"werewolf_den",map:"bear_cavern",title:"狼群的首領",situation:"基里爾帶著獵隊回來了。他聞到了外人的味道，也聞到了妻子們眼裡的背叛。",approaches:[{type:"支持祖萊卡",check:"說服 DC 14",outcome:"一半的狼群倒戈；基里爾被自己人拖倒"},{type:"用銀",check:"開戰",outcome:"銀器讓這場仗公平了一點"},{type:"談條件",check:"威嚇 DC 16",outcome:"基里爾答應不再擄孩子，換隊伍離開；他不會守信太久"}],fail_forward:"隊伍殺出了一條路，身後是整個狼群的嚎叫。從此在巴洛維亞的每一個夜晚，都得多留一個人守夜。",foes:[["bugbear",1],["dire_wolf",3]],sets:{success:["werewolves_emil"],setback:["werewolves_hostile"]}}]},{act:5,title:"修道院與亡魂",titleEn:"The Abbey and the Order",levelRange:"7",objective:"在山腳的村子與廢棄的騎士宅邸裡，分清楚誰還值得救，誰已經回不來",keyEvents:["克雷茲克不讓外人進村","修道院的鐘聲不該在半夜響","銀龍騎士團的亡魂還在巡邏","沼澤裡的老巫婆在養一顆寶石"],opening_text:"路的盡頭是一道石牆和兩座箭塔。牆後的村子很小，很乾淨，很安靜。山腰上有一座修道院，窗裡的燈是綠色的。",sites:[{id:"krezk",name:"克雷茲克與聖瑪可維亞修道院",map:"snow_town",blurb:"一座自給自足、不歡迎外人的山村。村民敬畏山上的修道院，也害怕它。",secret:"修道院長是一位墮落的天界生物，他相信只要為史特拉德造出一位完美的新娘，就能治好他並解放這片土地。他用屍塊縫出了瓦希爾卡。院裡的「病人」是被他治成半人半獸的一家子。村裡的聖池是塔蒂亞娜的靈魂記得的地方。"},{id:"argynvostholt",name:"銀龍宅邸",map:"ruined_keep",blurb:"山坡上一座半塌的大宅，屋頂上有一尊龍的雕像。裡面的騎士已經死了四百年，還在巡邏。",secret:"銀龍亞金沃斯特創立了銀龍騎士團，對抗過史特拉德的軍隊。龍死後，團長弗拉迪米爾被仇恨困住，成了亡魂；他不要史特拉德死，他要他永遠受苦。龍的頭骨被史特拉德放在鴉閣城堡當戰利品。"},{id:"berez",name:"柏瑞茲廢墟",map:"swamp_ruins",optional:!0,ifSkipped:{text:"芭芭·莉薩迦還在沼澤裡，她的小屋偶爾會在別處的霧中出現；她手上的那顆寶石也還在。"},blurb:"被河水淹掉的村子，只剩半截牆和一座長了腿的小屋。到處是稻草人。",rumour:"酒莊的第三顆寶石在一個老巫婆手上。",secret:"芭芭·莉薩迦自認是史特拉德的母親，用寶石驅動她會走路的屋子。瑪琳娜的紀念碑紀念的是塔蒂亞娜的另一次轉世，她被村民自己殺死，史特拉德因此淹了全村。"}],npcs:[{site:"krezk",name:"迪米崔·克雷茲科夫",role:"村長",description:"嚴肅、正直，上個月才埋了最後一個兒子。",interaction:"帶酒來，他就開門。",voice:"疲憊蒼老、背負著全村閉門鎖村重任的克雷茲克村長，眼神麻木冰冷。",flaw:"四個孩子相繼病逝讓他心如死灰，為了讓幼子復活甚至不惜默許白衣修道院長進行邪惡實驗。",tactics:"毫無戰鬥力，身披厚重皮襖，依仗堅固的木門與獵戶長弓守衛要塞。",deal:"只要小隊能運來一車巫師之泉紅酒撫慰全村，他會破例打開克雷茲克村大門並允許進入修道院。"},{site:"krezk",name:"修道院長",role:"修道院的主人",description:"年輕俊美，說話溫和，從不眨眼。",secrets:"他已經瘋了很久。被質疑時會露出天界生物的真面目。",voice:"優雅平靜、聲音如聖歌般悅耳但透著令人不寒而慄的異化神聖感（實為墮落天界神使）。",flaw:"試圖用屍塊縫合出一具完美新娘來「平息史特拉德的詛咒」，精神已徹底扭曲陷入神聖瘋狂。",tactics:"身為高階異界神侍，能變身為熾烈天使戰神，揮舞烈焰聖劍與大復原術，掌管天界雷霆。",deal:"只要為其尋來一件純白的新娘婚紗或出示聖徽進行崇高神學辯論，他會禮貌放行並贈予復活神蹟。"},{site:"krezk",name:"瓦希爾卡",role:"院長的作品",description:"蒼白安靜的少女，舉止像在背書。她在學怎麼當一個新娘。",secrets:"她不知道自己是用什麼做的。",voice:"喉嚨裡只能發出笨拙的咕嚕聲與粗重呼吸，由不同女屍縫合而成、披著新娘面紗的血肉魔像。",flaw:"智力如懵懂幼童，對周遭一切充滿好奇與恐懼，深信自己即將嫁給高貴的伯爵。",tactics:"體力無窮且免疫魔法雷電，巨掌拍擊能將板甲拍扁，遭受烈焰灼燒時會陷入短暫混亂。",deal:"只要以溫柔姿態對待她並贈予鮮花飾品，她會對隊伍產生依戀，拒絕聽從修道院長的攻擊指令。"},{site:"argynvostholt",name:"弗拉迪米爾·霍倫科",role:"騎士團長的亡魂",description:"坐在王座廳裡，握著劍，四百年沒有站起來。",secrets:"他恨的其實是自己。他下令殺死的那個人，是他所愛的人。",voice:"冰冷如墓穴玄冰、燃燒著永恆仇恨烈焰的白銀騎士團長亡魂，手中巨劍拖地泛出寒霜。",flaw:"沉溺於對史特拉德的永恆仇恨中無法自拔，甚至反對任何試圖殺死伯爵的人（他要伯爵永受折磨）。",tactics:"傳奇亡魂騎士，手持重型破甲巨劍發動雷霆斬殺，周身環繞仇恨怨念光環吸取全場體力。",deal:"唯有重燃阿金沃斯特莊園燈塔的阿爾貢神聖火炬，才能解開其數百年的怨恨執念，讓其靈魂安息。"},{site:"argynvostholt",name:"高弗瑞·格威林爵士",role:"亡魂騎士",description:"還記得騎士團原本是什麼樣子的人。",interaction:"他希望有人讓弗拉迪米爾放下，他自己做不到。",voice:"哀傷優雅、透著高尚騎士風骨的白銀騎士團亡魂，即便化為死靈依然行止端正。",flaw:"曾是弗拉迪米爾的生死至愛，目睹愛人陷入瘋狂復仇深淵而無比自責痛苦。",tactics:"身披殘破銀甲，手持騎士長劍施展神聖打擊，能在隊友身前構建靈體護盾阻隔亡靈詛咒。",deal:"只要小隊誓言讓白銀騎士團的榮譽重獲新生並點亮燈塔，他願違抗團長的狂暴命令暗中協助英雄。"},{site:"berez",name:"芭芭·莉薩迦",role:"沼澤的巫婆",description:"浮在一個巨人的頭骨裡，用史特拉德嬰兒時的洗澡水保持年輕。",voice:"瘋癲嘶啞、尖銳刺耳的沼澤老巫婆狂叫，自稱史特拉德伯爵真正的靈魂教母。",flaw:"對史特拉德懷有病態的母愛與偏執保護慾，對任何膽敢挑戰伯爵的英雄施以最殘酷的虐殺。",tactics:"乘坐巨大浮空骷髏頭戰鬥，操縱行走的巨石樹怪小屋踩踏全場，狂暴傾瀉八環連鎖閃電與毒雲。",deal:"狂暴的沼澤妖婆絕不談判；唯有斬斷樹怪小屋底座的魔根，並以烈火徹底焚燬其飛天骷髏頭！"}],encounters:["怨靈","幽影","屍妖","石像鬼","巨型蜘蛛","敵對魔導師"],treasures:["修道院的聖水","銀龍騎士團的紋章","酒莊的第三顆寶石","芭芭的法術書"],endCondition:"山腳的事告一段落，前面只剩雪山和那座城堡",strategic_nodes:[{id:"5-A1",site:"krezk",map:"castle_passage",title:"不開的門",situation:"箭塔上的人說，克雷茲克不收留外人。村長站在牆上，態度沒有商量的餘地，除非隊伍帶了酒來。",approaches:[{type:"帶酒來",check:"無",outcome:"門開了；村長親自道謝"},{type:"說服他",check:"說服 DC 16",outcome:"村長勉強放行，條件是天黑前離開"},{type:"另找路",check:"運動 DC 15",outcome:"翻過峭壁進村，沒有人歡迎"}],fail_forward:"門沒有開。隊伍只能在牆外過夜，聽了一整晚山上的鐘聲和不像人的笑聲。",calm:!0,sets:{success:["krezk_trusts"]},ifs:[["winery_saved","隊伍帶著酒莊的酒，或者帶著酒快到了的消息"],["winery_burned","酒莊毀了的消息已經傳到這裡，村長的臉色更難看"],["ireena_with_party","村長的妻子看見伊蕾娜，堅持讓這個姑娘進來歇一歇"]]},{id:"5-A2",site:"krezk",map:"village_courtyard",title:"最後一個兒子",situation:"村長的小兒子伊利亞剛病死。妻子不肯下葬，她聽說山上的院長能讓死人回來。村長不許她去。",approaches:[{type:"陪她上山",check:"說服 DC 12",outcome:"院長答應了，沒有提條件，這比提條件更讓人不安"},{type:"勸她放下",check:"洞悉 DC 14",outcome:"她哭了一場，同意下葬"},{type:"不介入",check:"無",outcome:"她自己半夜抱著孩子上了山"}],fail_forward:"孩子回來了。會走，會吃，會叫媽媽。就是不笑，也不眨眼。",calm:!0,sets:{success:[],setback:["ilya_raised"]}},{id:"5-A3",site:"krezk",map:"burial_chambers",title:"修道院的病人",situation:"修道院的院子裡關著一群人。有的長著狼的耳朵，有的有蝙蝠的翅膀，有的一半是驢。他們唱歌、打架、對著訪客流口水。院長說，他們來的時候都有病，是他治好的。",approaches:[{type:"跟病人說話",check:"洞悉 DC 13",outcome:"知道這一家人當初是自己求院長給他們「更好的身體」"},{type:"觀察院長",check:"宗教 DC 15",outcome:"認出他不是人，是天上來的東西，而且早就走偏了"},{type:"參觀他的工作",check:"調查 DC 13",outcome:"在樓上看見縫合的工具和一件新娘禮服"}],fail_forward:"有個病人掙脫了鍊子。等事情平息，院長的微笑一點也沒變，只是他開始把門鎖上。",foes:[["ghoul",2],["dire_wolf",1]],sets:{success:["abbot_exposed"]}},{id:"5-A4",site:"krezk",map:"sunlit_throne",title:"新娘",situation:"院長把瓦希爾卡介紹給隊伍。她會行禮，會微笑，會背一首詩。院長需要一件像樣的禮服，請隊伍去瓦拉基替他取。他很肯定史特拉德會喜歡她。",approaches:[{type:"跟瓦希爾卡說話",check:"說服 DC 13",outcome:"她問了一個院長沒教過的問題：我以前是誰"},{type:"當面反對",check:"說服 DC 17",outcome:"院長第一次皺眉；他說凡人不懂慈悲"},{type:"答應幫忙",check:"無",outcome:"院長很高興；瓦希爾卡看著隊伍，眼神像在求救"}],fail_forward:"院長展開了翅膀。他沒有殺人，他只是讓隊伍知道，他不是在請求。",foes:[["wraith",1]],sets:{success:[],setback:["abbot_bride"]},ifs:[["abbot_exposed","隊伍已經知道他是什麼；可以直接問他：這是誰的旨意？"],["ilya_raised","伊利亞站在院長身後，像另一件作品"]]},{id:"5-A5",site:"krezk",map:"shadow_cathedral",title:"聖池",situation:"村子北邊有一口結不了冰的池子，旁邊有一座小亭。伊蕾娜走近時，水面起了霧，霧裡有一個年輕人的聲音在叫另一個名字。天色忽然暗了下來。",approaches:[{type:"讓她走過去",check:"洞悉 DC 13",outcome:"她想起了一切；瑟蓋的靈魂伸出了手"},{type:"先警戒",check:"察覺 DC 14",outcome:"提前看見雲層裡那個身影"},{type:"拉住她",check:"運動 DC 13",outcome:"她沒有走進水裡；史特拉德的雷打在了空處"}],fail_forward:"史特拉德從天而降。他對那個聲音吼了一句話，池水炸開，等霧散去，伊蕾娜不見了。",foes:[["vampire_spawn",1]],sets:{success:["pool_blessing"],setback:["ireena_taken"]},ifs:[["!ireena_with_party","伊蕾娜不在隊伍裡。池邊只有一個年輕人的幽影，問隊伍有沒有見過一個紅髮的姑娘"],["strahd_met_road","他認得隊伍，這一次他不再客氣"]]},{id:"5-B1",site:"argynvostholt",map:"ruined_keep",title:"龍的家",situation:"大宅的門沒有關。大廳裡，一條由霧聚成的龍影抬起頭，看了隊伍一眼，然後朝樓上散去，像是在帶路。",approaches:[{type:"跟著龍影",check:"察覺 DC 12",outcome:"被帶到龍的墓室，在那裡聽見一句請求：把我的頭骨帶回來"},{type:"搜索大廳",check:"調查 DC 13",outcome:"從壁畫拼出騎士團的歷史"},{type:"小心前進",check:"隱匿 DC 14",outcome:"避開了巡邏的亡魂"}],fail_forward:"巡邏的亡魂把隊伍當成了入侵者。",foes:[["specter",2],["shadow",2]]},{id:"5-B2",site:"argynvostholt",map:"crypt_hall",title:"還記得誓言的人",situation:"禮拜堂裡跪著幾個騎士。其中一個轉過頭來，他的臉已經不是活人的臉，但他說話的方式還是。",approaches:[{type:"聽他說",check:"說服 DC 12",outcome:"高弗瑞說出騎士團的墮落，並請隊伍幫弗拉迪米爾解脫"},{type:"問頭骨",check:"歷史 DC 13",outcome:"他說頭骨在鴉閣城堡，燈塔只有它回來才會亮"},{type:"問他自己",check:"洞悉 DC 14",outcome:"他承認他與弗拉迪米爾不只是戰友"}],fail_forward:"其他的亡魂站了起來。高弗瑞擋在中間，要隊伍快走。",foes:[["wight",1],["specter",2]]},{id:"5-B3",site:"argynvostholt",map:"royal_hall",title:"坐了四百年的人",situation:"王座廳裡，弗拉迪米爾坐在那裡，膝上橫著劍。他知道隊伍是來殺史特拉德的。他不允許。",approaches:[{type:"讓他想起誓言",check:"說服 DC 16",outcome:"他握劍的手鬆了；他問，那我這四百年算什麼"},{type:"帶高弗瑞來",check:"無",outcome:"他看見那個人，站了起來"},{type:"打",check:"開戰",outcome:"他是隊伍至今遇過最強的對手"}],fail_forward:"弗拉迪米爾下了命令。從這一刻起，銀龍騎士團的亡魂會在巴洛維亞的每一條路上獵殺隊伍。",foes:[["wight",1],["wraith",1]],sets:{success:["vladimir_released"],setback:["vladimir_enemy"]}},{id:"5-B4",site:"argynvostholt",map:"ruined_keep",title:"燈塔",situation:"屋頂的塔樓是空的，中央有一個放東西的石台。龍影盤在上面，等著。",approaches:[{type:"答應帶回頭骨",check:"無",outcome:"龍影低下頭；這個承諾要到城堡裡才能兌現"},{type:"問龍",check:"奧秘 DC 14",outcome:"知道燈塔亮起時，這片土地上所有對抗史特拉德的人都會得到庇護"},{type:"搜索塔樓",check:"調查 DC 13",outcome:"找到騎士團留下的一件遺物"}],fail_forward:"龍影散了。隊伍不確定它是不是還相信他們。",calm:!0,foes:[],ifs:[["vladimir_released","弗拉迪米爾和他的騎士們在樓下列隊，向離開的人行禮"]]},{id:"5-C1",site:"berez",map:"night_marsh",title:"稻草人",situation:"沼澤裡到處是稻草人，每一個的臉都轉向同一棟長了腳的小屋。有幾個在隊伍經過之後換了位置。",approaches:[{type:"潛過去",check:"隱匿 DC 15",outcome:"沒有驚動它們"},{type:"先毀掉稻草人",check:"開戰",outcome:"它們的爪子是鐮刀做的"},{type:"找別的路",check:"生存 DC 14",outcome:"從淹沒的教堂繞過去，發現一座紀念碑"}],fail_forward:"稻草人一起轉了過來。屋子裡的燈亮了。",foes:[["shadow",3]]},{id:"5-C2",site:"berez",map:"swamp_ruins",title:"瑪琳娜的紀念碑",situation:"廢墟邊有一座石碑，刻著一個女人的像。她的臉，隊伍見過。",approaches:[{type:"讀碑文",check:"歷史 DC 12",outcome:"知道這個村子為什麼被淹：村民殺了史特拉德愛的女人"},{type:"想通這件事",check:"洞悉 DC 13",outcome:"明白伊蕾娜不是第一個，也知道史特拉德每一次都輸"},{type:"搜索基石",check:"調查 DC 14",outcome:"基石下有東西"}],fail_forward:"隊伍在碑前待得太久。沼澤的霧裡，有一個巨大的頭骨浮了起來。",calm:!0,foes:[],ifs:[["ireena_with_party","伊蕾娜自己站在碑前，很久沒有說話"]]},{id:"5-C3",site:"berez",map:"swamp_ruins",title:"會走路的屋子",situation:"小屋站了起來。它的腳是樹根，屋裡的地板下有一顆發光的寶石在跳動。老巫婆坐在一個巨大的頭骨裡飛在半空，罵隊伍是來偷她兒子東西的賊。",approaches:[{type:"搶寶石",check:"特技 DC 16",outcome:"寶石一離開，屋子就倒了"},{type:"對付巫婆",check:"開戰",outcome:"她的法術很狠，屋子也在踩人"},{type:"騙她",check:"欺瞞 DC 16",outcome:"讓她相信隊伍是史特拉德派來的，換到幾分鐘"}],fail_forward:"隊伍逃出了沼澤，沒拿到寶石。背後的屋子追到水邊才停下。",foes:[["mage_enemy",1],["troll",1]],sets:{success:["baba_slain","gem_recovered"]}}]},{act:6,title:"琥珀神殿",titleEn:"The Amber Temple",levelRange:"8",objective:"到雪山上史特拉德得到力量的地方去，帶著答案回來，而不是帶著別的東西",keyEvents:["山路上的關口有東西守著","神殿裡關著比史特拉德更老的東西","它們很樂意送禮"],opening_text:"路往上走進了雪線。風大得聽不見彼此說話。維斯塔尼人說，山上有一座神殿，是一群好法師蓋來關住壞東西的。後來法師都死了，壞東西還在。",sites:[{id:"tsolenka",name:"措倫卡隘口",map:"ice_bridge",blurb:"峭壁上的一道關門和一座橫跨深谷的石橋。關門裡燒著綠色的火。",secret:"關口是古時的守衛工事。橋上有東西會把人撞下去。"},{id:"amber_temple",name:"琥珀神殿",map:"ice_sanctum",blurb:"嵌在山壁裡的巨大神殿。正殿的神像沒有臉。每一間側室裡都立著一塊琥珀，裡面有影子在動。",secret:"琥珀裡封著被稱為「黑暗力量」的殘存意志，它們給人力量，並拿走一點人性。史特拉德就是在這裡立約的。守護神殿的巫妖已經忘了自己是誰。"}],npcs:[{site:"amber_temple",name:"艾克斯坦瑟",role:"失憶的巫妖",description:"乾瘦、客氣，把訪客當成來借書的學者。他不記得自己的名字，也不記得自己有多危險。",interaction:"幫他想起名字，他會回答任何問題。",voice:"迷茫滑稽、說話顛三倒四但偶爾爆發出驚天奧術威壓的半失憶古老巫妖。",flaw:"漫長歲月讓其魂匣受損，遺忘了絕大部分記憶，甚至記不清自己的名字與禁忌魔法。",tactics:"身為萬年老巫妖，本能掌握九環高階法術位，揮手即可施展時間停止與解離術自衛。",deal:"只要對其以禮相待並施展高階心靈修復術助其找回一絲記憶碎片，他樂意指點琥珀神殿深處的黑暗遺產。"},{site:"amber_temple",name:"卡西米爾·維利科夫",role:"黃昏精靈",description:"瓦拉基外營地的精靈，割了耳朵贖罪。他來這裡求一個奇蹟。",secrets:"他要復活被他親手處死的妹妹帕翠娜；她生前想嫁給史特拉德。",voice:"憂鬱悲涼、目光宛如深淵死水的黃昏精靈長老，雙耳被史特拉德殘忍割去。",flaw:"執著於復活數百年前被石刑處死的妹妹帕特里娜，為此不惜向琥珀神殿的邪神暗影做交易。",tactics:"擅長高階冰霜與塑能法術，施展暴風雪掩護前進，在關鍵時刻能引導精靈秘術突破封印。",deal:"答應護送其深入琥珀神殿尋找復活秘法，他願以全部生命與古老精靈知識輔助小隊奪取日光聖徽。"}],encounters:["石像鬼","骷髏兵","怨靈","敵對魔導師","冰霜巨人"],treasures:["神殿的法術書","琥珀碎片","關於史特拉德立約的記載"],endCondition:"隊伍帶著在山上得到的東西下山，鴉閣城堡就在眼前",strategic_nodes:[{id:"6-A1",site:"tsolenka",map:"snow_pass",title:"綠火的關門",situation:"關門上的雕像是兩隻巨鳥。門洞裡的火不發熱，穿過去的人說不出自己看見了什麼。",approaches:[{type:"找出通過的方法",check:"奧秘 DC 14",outcome:"火是屏障不是陷阱，有規律可循"},{type:"攀過去",check:"運動 DC 15",outcome:"從關牆外側繞，一失手就是深谷"},{type:"硬闖",check:"無",outcome:"火燒過每個人，雕像動了"}],fail_forward:"雕像撲了下來。等隊伍過了關，每個人身上都結著霜和血。",foes:[["gargoyle",2]]},{id:"6-A2",site:"tsolenka",map:"ice_bridge",title:"風裡的橋",situation:"石橋很窄，沒有欄杆，兩頭各有一尊騎士像。橋中央，一頭長角的巨獸低下了頭。",approaches:[{type:"一個一個過",check:"特技 DC 14",outcome:"貼著橋面爬，風搶不走人"},{type:"引開牠",check:"馴獸 DC 15",outcome:"讓牠衝向空處"},{type:"正面擋住",check:"開戰",outcome:"在橋上打一場不能退的仗"}],fail_forward:"有人被撞下了橋。繩子拉住了他，但行囊掉進了谷底。",foes:[["minotaur",1]]},{id:"6-B1",site:"amber_temple",map:"ice_sanctum",title:"沒有臉的神",situation:"正殿裡有一尊巨大的神像，臉被鑿掉了。火從神像頭部的暗室裡射下來，那裡有人。",approaches:[{type:"找掩護前進",check:"隱匿 DC 14",outcome:"摸到神像背後的樓梯"},{type:"喊話",check:"說服 DC 15",outcome:"上面的人停手了；他們是被困在這裡的山民，不是守衛"},{type:"衝上去",check:"開戰",outcome:"在窄梯上硬攻"}],fail_forward:"隊伍被火逼進了側廊，掉進了他們本來不打算走的那一半神殿。",foes:[["mage_enemy",1],["bandit_captain",1]]},{id:"6-B2",site:"amber_temple",map:"academy_library",title:"忘了名字的管理員",situation:"圖書室裡有個枯瘦的人在整理書。他很高興有訪客，抱歉說自己記性不好，連名字都想不起來了。他的眼眶裡有兩點光。",approaches:[{type:"幫他回想",check:"調查 DC 14",outcome:"從他自己的藏書裡找到他的名字；他非常感謝"},{type:"請教他",check:"說服 DC 13",outcome:"他樂意介紹神殿，並提醒哪些房間「不太安全」"},{type:"認出他是什麼",check:"奧秘 DC 15",outcome:"知道絕不能在這裡跟他動手"}],fail_forward:"他忽然想起了一點事。不是名字，是他原本該對闖入者做的事。",calm:!0,sets:{success:["exethanter_restored"]}},{id:"6-B3",site:"amber_temple",map:"treasure_store",title:"琥珀裡的聲音",situation:"每一塊琥珀都在跟靠近的人說話，而且只說那個人最想聽的。它們不要錢，不要靈魂，只要你說「好」。",approaches:[{type:"全部拒絕",check:"洞悉 DC 15",outcome:"看穿了每一個提議底下的代價"},{type:"問它們史特拉德的事",check:"奧秘 DC 15",outcome:"其中一個笑了，說他當年問的問題跟你一樣"},{type:"接受一個",check:"無",outcome:"力量是真的，代價也是"}],fail_forward:"有人答應了。他自己都不確定是什麼時候開的口。",foes:[],calm:!0,sets:{success:["strahd_secret_known"],setback:["dark_gift_taken","strahd_secret_known"]},ifs:[["house_appeased","在死亡之屋動手的那個人，琥珀特別喜歡他"],["exethanter_restored","巫妖在一旁解說每一塊琥珀裡是誰，並建議一個都別碰"]]},{id:"6-B4",site:"amber_temple",map:"ice_chasm",title:"求奇蹟的人",situation:"神殿深處，一個沒有耳朵的精靈跪在一塊琥珀前。他認得隊伍。他說他只求一件事，把他妹妹還給他。",approaches:[{type:"勸他回頭",check:"說服 DC 16",outcome:"他說出了帕翠娜是誰，以及他為什麼不該這麼做，然後還是哭了"},{type:"幫他",check:"無",outcome:"帕翠娜回來了。她謝過哥哥，然後問去城堡的路"},{type:"阻止他",check:"開戰",outcome:"他不會手下留情"}],fail_forward:"儀式完成了。一個女人從琥珀的光裡走出來，她看隊伍的眼神像在看擋路的東西。",foes:[["mage_enemy",1]],sets:{success:[],setback:["kasimir_patrina"]}},{id:"6-B5",site:"amber_temple",map:"treasure_store",title:"下山",situation:"神殿開始不歡迎客人了。來時的路上多了東西，雪在外面下得更大。隊伍得帶著知道的事離開。",approaches:[{type:"照原路退",check:"生存 DC 14",outcome:"在暴風雪封山前過了橋"},{type:"請巫妖帶路",check:"無",outcome:"他知道一條近路"},{type:"殺出去",check:"開戰",outcome:"神殿的守衛不讓知道秘密的人走"}],fail_forward:"隊伍下了山，少了一些東西：體力、補給，或者某個人眼裡原有的光。",foes:[["wraith",1],["skeleton",4]],ifs:[["exethanter_restored","巫妖送隊伍到門口，像送別來借書的朋友"],["dark_gift_taken","接受饋贈的人發現自己在暴風雪裡一點也不冷"]]}]},{act:7,title:"鴉閣城堡",titleEn:"Castle Ravenloft",levelRange:"9",objective:"走進他的家，找到他，結束這件事",keyEvents:["城門自己打開","主人請客人用餐","城堡裡的每一個房間都是他的記憶","塔羅卡說過他在哪裡"],opening_text:"吊橋自己放了下來。城堡比從任何地方看都大，千尺高的石柱上立著尖塔，沒有一扇窗裡有光，只有大門裡透出燭火。管風琴的聲音從深處傳來。",sites:[{id:"ravenloft",name:"鴉閣城堡",map:"castle_passage",blurb:"史特拉德以母親之名命名的城堡。四百年來，進去的人很多，出來的很少。",secret:"城堡北塔裡有一顆巨大的水晶心臟，替史特拉德承受傷害。地下墓穴裡有他的棺槨，他被打敗時會化成霧逃回那裡。他的弟弟瑟蓋葬在墓穴深處。"}],npcs:[{site:"ravenloft",name:"史特拉德·馮·扎羅維奇",role:"城堡的主人",description:"在自己家裡，他不再是客氣的領主。",tactics:"召喚狼群與蝙蝠狂潮，化霧瞬移，輕抬手指便能施展魅惑人類與高階護盾偏折攻擊。",weakness:"陽光、流水、聖徽與太陽劍；心臟被毀後他才會真的受傷；他不能未經邀請進入別人的居所；他放不下塔蒂亞娜。",voice:"優雅高貴、極具統治者威嚴與殘酷玩味的領主男中音，每一字都帶著絕對的主宰力量。",flaw:"極度自負傲慢，將闖入者視為供其消遣的老鼠，在初遇時不屑於直接碾殺獵物。",deal:"以最高規格的貴族禮節向小隊發出鴉閣堡晚宴邀請函，嘲弄小隊的掙扎並享受貓捉老鼠的樂趣。"},{site:"ravenloft",name:"拉哈丁",role:"總管",description:"黃昏精靈，侍奉了史特拉德一輩子。靠近他的人會聽見他殺過的人的慘叫。",voice:"冰冷刺骨、不帶絲毫人類情感的黃昏精靈大總管腔調，周身伴隨數千名受難亡魂的淒厲哀嚎耳語。",flaw:"盲目誓死效忠馮·扎羅維奇家族數百年，視史特拉德的意志為至高神旨，毫無自我救贖渴望。",tactics:"雙持精鋼彎刀發動無影狂斬，自帶「受難耳語」光環每輪震碎敵人心智，擅長極限身法突進。",deal:"忠心耿耿的冷血總管絕不背叛；唯有以雷霆武力斬下其頭顱，才能踏破通往伯爵私人聖所的最後防線。"},{site:"ravenloft",name:"希瑞爾·范·溫德",role:"會計",description:"被鎖在帳房裡的老人，替城堡記了一輩子的帳，知道每一樣東西放在哪。",interaction:"答應帶他出去，他就畫地圖。",voice:"膽小自私、只在乎記賬本與金幣數字的城堡僕役長老頭，說話尖酸刻薄。",flaw:"貪財好利且深懼城堡內的亡靈生物，只要稍微受到武力恐嚇便會全盤交代。",tactics:"毫無戰鬥力，遇險會揮舞羽毛筆與厚重賬本亂擋，隨後尖叫著鑽進桌底下。",deal:"塞給他一袋沉甸甸的金幣或以利刃架在脖子上，他會交出城堡各處隱秘寶庫的鑰匙與巡邏路線圖。"},{site:"ravenloft",name:"葛楚妲",role:"村裡來的女孩",description:"瑪麗的女兒，相信自己是來當公主的。",voice:"天真爛漫、眼神充滿夢幻少女幻想的嬌弱少女，身穿華麗紅裙在城堡客房中梳頭。",flaw:"被史特拉德的虛假甜言蜜語徹底洗腦，深信自己是伯爵未來的尊貴王妃，對危險渾然不覺。",tactics:"毫無戰鬥力，遭到強行拉扯時會任性哭鬧並呼喚伯爵救命。",deal:"出示其母親瑪麗縫製的破洋娃娃並講述母親的痛苦，能打破其虛妄幻想，乖乖跟隨小隊逃離城堡。"},{site:"ravenloft",name:"埃米爾·托倫斯基",role:"被囚的狼人",description:"被關在地牢裡的前狼群首領。",voice:"狂暴低吼中帶著無盡痛苦的雄狼人嗓音，粗重鐵鏈將其琵琶骨死死銬在潮濕地牢石柱上。",flaw:"長期幽禁導致精神高度敏感，對基里爾的背叛恨之入骨，極度擔憂妻子祖萊卡的安危。",tactics:"砸碎鐵鏈後化身暴怒巨狼，利爪揮擊撕裂重甲，狂暴狂熱戰力甚至能壓制吸血鬼衍體。",deal:"告知其妻子祖萊卡正在安全等待，並斬斷其身上束縛的精鋼鎖鏈，他會咆哮著成為小隊最強近戰猛獸盟友。"}],boss:{name:"史特拉德·馮·扎羅維奇",tactics:"打了就走，穿牆化霧，先對付拿聖物的人。",weakness:"陽光、聖徽、太陽劍；先毀掉心臟。"},encounters:["吸血鬼衍體","石像鬼","怨靈","恐狼","活化鎧甲","屍妖"],treasures:["銀龍亞金沃斯特的頭骨","城堡的寶庫","史特拉德的日記","瑟蓋的遺物"],endCondition:"史特拉德被擊敗，或者隊伍成了城堡的一部分",strategic_nodes:[{id:"7-A",site:"ravenloft",map:"castle_passage",title:"請進",situation:"大門自己開了。門廳裡站著一位面無表情的精靈，他鞠躬，說主人正在等。他身邊的空氣裡有很多人在尖叫。",approaches:[{type:"隨他去",check:"無",outcome:"被領往餐廳；一路上看得見城堡的格局"},{type:"分頭探路",check:"隱匿 DC 16",outcome:"有人趁機溜進了側廊"},{type:"當場動手",check:"開戰",outcome:"拉哈丁一個人就夠難纏了，而且石像鬼從天花板上下來"}],fail_forward:"拉哈丁退進了陰影裡。隊伍一進門就見了血，而且整座城堡都知道他們來了。",foes:[["veteran",1],["gargoyle",2]],sets:{success:["dinner_accepted"],setback:["rahadin_slain"]},ifs:[["ireena_taken","拉哈丁說：小姐也在等各位"],["abbot_bride","門廳裡多了一位穿著禮服、安靜站著的少女"],["vladimir_enemy","門外的霧裡，亡魂騎士的馬蹄聲追到了吊橋邊"]]},{id:"7-B",site:"ravenloft",map:"banquet_manor",title:"晚宴",situation:"長桌上擺滿了熱菜和酒。主位上的人在彈管風琴，背對著客人。他轉過身來，為沒能更早招待各位致歉。",approaches:[{type:"陪他談",check:"洞悉 DC 15",outcome:"他說了很多；聽得出他寂寞、驕傲，也聽得出他在試探誰可以收為己用"},{type:"戳破他",check:"說服 DC 16",outcome:"提起瑟蓋與塔蒂亞娜，他第一次失態"},{type:"不上當",check:"察覺 DC 15",outcome:"看出主位上的只是幻象，真正的他在別處看著"}],fail_forward:"燭火全滅了。等再亮起來，桌邊少了一個人，門也不在原來的地方。",foes:[["vampire_spawn",2]],ifs:[["strahd_secret_known","隊伍知道他在琥珀神殿答應了什麼；說出來，他的笑容不見了"],["dark_gift_taken","他舉杯向接受饋贈的那個人致意，稱他為同類"],["dinner_accepted","他守著待客之道，這頓飯吃完之前不會動手"],["house_defied","他說，從死亡之屋那天起我就在看各位"]]},{id:"7-C",site:"ravenloft",map:"treasure_store",title:"帳房裡的老人",situation:"一間堆滿帳本的房間，一個被鍊子鎖在桌邊的老人還在記帳。他頭也不抬地問：是來查帳的，還是來死的？",approaches:[{type:"放了他",check:"巧手 DC 14",outcome:"希瑞爾畫出寶庫、心臟塔與墓穴的路"},{type:"問葛楚妲",check:"說服 DC 13",outcome:"他說有個村姑被安排在主人的臥房，還在試衣服"},{type:"問頭骨",check:"調查 DC 13",outcome:"帳上寫得很清楚：銀龍頭骨一顆，陳列於某廳"}],fail_forward:"老人搖了搖桌上的鈴。他抱歉地說，這是他的工作。",foes:[["animated_armor",2]],ifs:[["!skull_returned","隊伍答應過一條龍。頭骨就在這座城堡裡"]]},{id:"7-D",site:"ravenloft",map:"crypt_hall",title:"被關著的人",situation:"地牢半淹在水裡。牢房裡有人。有的是史特拉德的敵人，有的是他的玩具，有的兩者都是。",approaches:[{type:"救人",check:"運動 DC 14",outcome:"在水漲上來之前打開牢門"},{type:"認人",check:"洞悉 DC 13",outcome:"分得出誰是真的囚犯，誰是放在這裡等人來救的陷阱"},{type:"找埃米爾",check:"說服 DC 14",outcome:"他不相信任何人，除非提起祖萊卡"}],fail_forward:"牢門開了，水也漲了。救出來的人裡有一個不是人。",foes:[["vampire_spawn",1],["ghoul",3]],ifs:[["werewolves_emil","祖萊卡的信物讓埃米爾立刻站到隊伍這邊"],["ireena_taken","伊蕾娜不在這裡。她被當成客人，不是囚犯"]]},{id:"7-E",site:"ravenloft",map:"blue_tower",title:"悲傷之心",tactical:{"scenarioId":"blue_tower","heroFormation":"bottom","foeFormation":"top","ambushMode":"normal","lighting":"dim","objectiveName":"擊碎拉文羅夫的「悲傷之心」","interactables":[{"kind":"crystal","name":"悲傷之心水晶心臟","dc":14,"rewardEffect":"weaken_foes","rewardDesc":"悲傷之心碎裂！城堡內施特拉德的護盾屏障崩解！"}],"script":{"missionGoal":"突破高塔血族守衛，徹底擊碎「悲傷之心」","opening":[{"speaker":"我方隊長","side":"hero","line":"那顆跳動的巨大紅水晶就是施特拉德的護盾來源——打碎它！"}],"propLine":{"speaker":"我方隊員","side":"hero","line":"水晶心臟碎了！伯爵再也沒有傷害吸收屏障了！"}}},situation:"北塔是空心的。塔頂懸著一顆兩人高的紅色水晶，在跳。每跳一下，整座城堡都跟著一震。通往它的只有一道沒有欄杆的螺旋梯。",approaches:[{type:"爬上去毀掉它",check:"特技 DC 15",outcome:"水晶碎了，城堡發出一聲像人的慘叫"},{type:"從下面打",check:"開戰",outcome:"塔在搖，守衛從每一層湧出來"},{type:"找它的弱點",check:"奧秘 DC 15",outcome:"知道它與史特拉德相連：它碎的時候，他會立刻知道，也會立刻趕來"}],fail_forward:"樓梯塌了一段。心臟還在跳，而他已經知道隊伍在哪。",foes:[["vampire_spawn",2],["gargoyle",1]],sets:{success:["heart_destroyed"]}},{id:"7-F",site:"ravenloft",map:"banquet_manor",title:"新娘們",situation:"臥房裡有三個女人。她們美麗、蒼白，對新來的客人很有興趣。隔壁房裡，一個村姑正對著鏡子試一件她這輩子沒見過的禮服。",approaches:[{type:"帶葛楚妲走",check:"說服 DC 14",outcome:"她不想走，直到看見鏡子裡沒有那三個女人的影子"},{type:"挑撥她們",check:"欺瞞 DC 15",outcome:"她們之間的嫉妒比對主人的忠誠深"},{type:"解決她們",check:"開戰",outcome:"三個衍體，在她們自己的地盤"}],fail_forward:"她們沒有殺人。她們只是各自在一個人的頸子上留下了記號，然後笑著退進牆裡。",foes:[["vampire_spawn",3]],sets:{success:["brides_dealt"]},ifs:[["ireena_taken","伊蕾娜在這裡，穿著白色的禮服。她還是她自己，但時間不多了"],["abbot_bride","瓦希爾卡也在這裡。新娘們把她當成笑話，她在等有人告訴她該怎麼辦"],["kasimir_patrina","帕翠娜已經到了，她打算成為這裡的女主人"]]},{id:"7-G",site:"ravenloft",map:"burial_chambers",title:"地下墓穴",situation:"城堡底下是一整片墓穴，一排一排的墓室，每一間門上都有名字和一句話。蝙蝠像一層會動的天花板。最深處有三道門：他的父母、他的弟弟、他自己。",approaches:[{type:"找到他的棺槨",check:"調查 DC 15",outcome:"知道他被打敗後會逃回哪裡，並在那裡等著"},{type:"開瑟蓋的墓",check:"宗教 DC 14",outcome:"四百年來沒有腐壞的遺體；這裡是整座城堡唯一讓史特拉德不敢久留的地方"},{type:"取回頭骨",check:"運動 DC 14",outcome:"把銀龍的頭骨從陳列處搬下來"}],fail_forward:"墓穴的閘門落了下來，把隊伍分成兩半。黑暗裡有翅膀的聲音。",foes:[["wight",2],["wraith",1]],sets:{success:["skull_returned"]},ifs:[["pool_blessing","伊蕾娜在瑟蓋的墓前站了很久，說她想起來了"],["vladimir_released","頭骨一離開陳列處，遠處山坡上亮起了一道銀光"]]},{id:"7-H",site:"ravenloft",map:"sunlit_throne",title:"塔羅卡說的地方",tactical:{"scenarioId":"sunlit_throne","heroFormation":"bottom","foeFormation":"top","foeWaves":true,"ambushMode":"normal","lighting":"dark","objectiveName":"在預言王座徹底終結施特拉德","namedFoes":[{"template":"vampire_spawn","name":"施特拉德·馮·扎洛維奇伯爵","isBoss":true}],"interactables":[{"kind":"crystal","name":"太陽聖徽聚光鏡","dc":14,"rewardEffect":"aoe_holy_burst","rewardDesc":"日光傾瀉王座大廳！施特拉德在聖光中劇烈灼傷！"}],"script":{"missionGoal":"在拉文羅夫王座廳擊敗吸血鬼領主施特拉德","opening":[{"speaker":"施特拉德伯爵","side":"foe","line":"巴洛維亞的一切皆屬於我……你們只是黑夜裡最後的餘燼。"},{"speaker":"我方隊長","side":"hero","line":"今晚，這片詛咒迷霧就要徹底散去！舉起聖徽迎戰！"}],"triggers":{"foeHalfHp":{"speaker":"施特拉德伯爵","side":"foe","line":"放肆的凡人！竟敢傷及吾之真身——荒野魔狼，撕碎他們！"},"waveArrive":{"speaker":"施特拉德伯爵","side":"foe","line":"黑夜的眷族們，現身吧！"}},"ending":{"victory":[{"speaker":"我方隊長","side":"hero","line":"施特拉德化作塵埃了……陽光終於重新照進巴洛維亞！"}]}}},situation:"牌上說過他會在這裡。他確實在。沒有隨從，沒有幻象。他說他等這一刻等了很久，並問隊伍最後一次：有沒有人想留下來。",approaches:[{type:"用聖物對付他",check:"開戰",outcome:"聖徽的光、太陽劍的刃、書裡寫的弱點，每一樣都是用之前的路換來的"},{type:"用他的過去對付他",check:"說服 DC 17",outcome:"提起瑟蓋、提起塔蒂亞娜、提起他在琥珀前說的那個「好」；他動搖的每一刻都是破綻"},{type:"把他逼回棺槨",check:"開戰",outcome:"打到他化霧逃走，然後在墓穴裡結束"}],fail_forward:"隊伍倒下了。他沒有殺他們。他一個一個看過去，像在挑選，然後說：巴洛維亞需要新的面孔。",foes:[["vampire_spawn",1],["dire_wolf",2]],ifs:[["heart_destroyed","心臟已毀，他受的每一道傷都是真的"],["!heart_destroyed","心臟還在跳，替他擋下了最初的重傷；他知道隊伍沒去北塔"],["has_sword","太陽劍在這裡是白晝"],["has_symbol","聖徽讓他無法直視持有的人"],["has_tome","隊伍讀過他的日記，知道他每一次轉身之前的習慣"],["has_ally","命定的盟友就在隊伍身邊，這一戰他們不是孤軍"],["missed_sword","太陽劍不在隊伍手上；他特地提起這件事"],["ireena_with_party","伊蕾娜在場。他每一次出手都避開她，這是他最大的破綻"],["ireena_taken","伊蕾娜站在他身後；她還沒有完全屬於他"],["pool_blessing","她叫了他一聲，用的是四百年前的語氣，說的是「不」"],["skull_returned","銀龍的燈塔亮著，光從窗外照進來，他的狼與蝙蝠不敢靠近"],["rictavio_trusts","范李希頓帶著木樁在外面守著他的退路"],["ezmerelda_ally","艾茲梅瑞妲在墓穴裡埋了足夠的炸藥"],["werewolves_emil","城外的狼群今晚不聽他的"],["werewolves_hostile","他召來的不只是狼，還有狼人"],["wachter_rules","瓦拉基今晚為他點了燈，他比平常更強"],["dark_gift_taken","他對接受饋贈的人說：你會明白我的，再過一百年"],["brides_dealt","沒有人從牆裡出來幫他"],["kasimir_patrina","帕翠娜站在他那一邊"],["abbot_bride","瓦希爾卡擋在他面前，或者擋在隊伍面前，看之前有沒有人對她好"]]}]}]};
